"use client";
// koipond — <KoiPond />: a living koi pond for any page.
//
//   <KoiPond fish={9} look="violet" />
//
// Move the pointer slowly and curious koi come to look; move fast and the shy ones dart away.
// Tap the water for ripples, double-tap (or long-press) to drop food. Pauses when off screen and
// shows a still pond for people who prefer reduced motion.
import { forwardRef, useEffect, useImperativeHandle, useRef } from "react";
import { drawScene, drawTop, drawUnder, stonesFor } from "./draw";
import { createProps3D } from "./props3d";
import { createWater, type Look } from "./gl";
import { createStage } from "./stage";
import { createFish3D } from "./fish3d";
import { Pond, type V } from "./sim";

export const LOOKS: Record<string, Look> = {
  ink: { mode: "ink", palette: ["#000", "#000", "#000", "#000"], deep: "#283850", shallow: "#80998c", tint: "#ffffff", pixel: 1, floor: "pebbles", caustics: 1, clarity: 1, waves: 1 },
  garden: { mode: "color", palette: ["#000", "#000", "#000", "#000"], deep: "#4a5552", shallow: "#8a9a91", tint: "#ffffff", pixel: 1, floor: "pebbles", caustics: .45, clarity: .6, waves: .8, bright: .8, film: true, absorb: [1.1, .95, 1.02] },
  lagoon: { mode: "color", palette: ["#000", "#000", "#000", "#000"], deep: "#08758c", shallow: "#25b8b4", tint: "#ffffff", pixel: 1, floor: "sand", caustics: 1.2, clarity: 1.0, waves: 1.3, bright: .85 },
  violet: { mode: "dither", palette: ["#09080f", "#2a2160", "#6c5ce7", "#e4dfff"], deep: "#05040a", shallow: "#15122a", pixel: 2 },
  mono: { mode: "dither", palette: ["#0c0c0c", "#3a3a3a", "#9a9a9a", "#f2f0ea"], deep: "#050505", shallow: "#1b1b1b", pixel: 2 },
  ember: { mode: "dither", palette: ["#0d0806", "#5a1f12", "#e2451c", "#fde6c8"], deep: "#070403", shallow: "#1c0f0a", pixel: 2 },
  natural: { mode: "color", palette: ["#000", "#000", "#000", "#000"], deep: "#062a33", shallow: "#175a56", tint: "#f2fbf8", pixel: 1, caustics: .45, waves: .8 },
};

export interface KoiPondHandle {
  feed(x: number, y: number): void;
  ripple(x: number, y: number): void;
  /** Hold a shape: one slot per fish (0..1 coordinates), plus the swim direction at each slot. */
  formation(slots: V[] | null, flow?: V[]): void;
  /** Push the water: fish and pads drift with it. */
  current(x: number, y: number): void;
  pond(): Pond | null;
}

export interface KoiPondProps {
  /** Number of koi. */
  fish?: number;
  /** Art style: "natural", "ink", "garden", "violet", "ember", "mono", or your own Look. Can change live. */
  look?: keyof typeof LOOKS | Look;
  /** Fish size relative to the short side of the pond. */
  fishSize?: number;
  /** Floating lily pads (some flower). */
  pads?: number;
  /** Sakura petals drifting down onto the water. */
  petals?: number;
  /** Small dark fish darting between the koi. */
  minnows?: number;
  /** Same seed, same pond. */
  seed?: number;
  /** Pointer, taps, feeding and scroll. */
  interactive?: boolean;
  /** 0..1 rain on the surface. */
  rain?: number;
  /** Override parts of the look: water colours, light (caustics), waves. */
  water?: { shallow?: string; deep?: string; caustics?: number; waves?: number; clarity?: number };
  /** A small cluster of rocks in the lower-left corner. */
  border?: boolean;
  /** Scrolling (wheel or swipe) over the pond pushes the water: fish, petals and pads stream with it. */
  scrollCurrent?: boolean;
  /** Over the pond, the pointer becomes a soft ring with a dot (hidden on touch screens). */
  cursor?: boolean;
  /** Resolution of the simulation relative to the element (lower = chunkier, faster). */
  scale?: number;
  className?: string;
  style?: React.CSSProperties;
}

export const KoiPond = forwardRef<KoiPondHandle, KoiPondProps>(function KoiPond(
  { fish = 12, look = "natural", fishSize = 0.18, pads = 4, petals = 10, minnows = 4, seed = 7, interactive = true, scale = 1, rain = 0.4, water, cursor = true, scrollCurrent = true, border = true, className, style }, ref,
) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pondRef = useRef<Pond | null>(null);
  const sizeRef = useRef({ w: 1, h: 1 });
  // the look can change at any time without disturbing the fish
  const themeRef = useRef<Look>(LOOKS.violet);
  const base = typeof look === "string" ? LOOKS[look] ?? LOOKS.violet : look;
  themeRef.current = water ? { ...base, ...Object.fromEntries(Object.entries(water).filter(([, v]) => v !== undefined)) } : base;
  if (pondRef.current) pondRef.current.rain = rain;
  const styleName = typeof look === "string" ? look : "natural";
  const styleRef = useRef(styleName); styleRef.current = styleName;
  const borderRef = useRef(border); borderRef.current = border;
  const rainRef = useRef(rain); rainRef.current = rain;
  const dropRef = useRef<HTMLDivElement>(null);
  const dotRef = useRef<HTMLDivElement>(null);
  // where the last tap or click was (0..1): a style change spreads out from there
  const lastTapRef = useRef<[number, number]>([0.5, 0.5]);

  useImperativeHandle(ref, () => ({
    feed: (x, y) => pondRef.current?.feed(x * sizeRef.current.w, y * sizeRef.current.h),
    ripple: (x, y) => pondRef.current?.ripple(x * sizeRef.current.w, y * sizeRef.current.h, "tap"),
    formation: (slots, flow) => pondRef.current?.setFormation(slots && slots.map((s) => ({ x: s.x * sizeRef.current.w, y: s.y * sizeRef.current.h })), flow),
    current: (x, y) => { if (pondRef.current) pondRef.current.current = { x, y }; },
    pond: () => pondRef.current,
  }), []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    // realistic WebGL2 water when available; the simple stylised water otherwise
    // everything on one shared three.js renderer (no copies between GPU contexts)
    let stage: ReturnType<typeof createStage> | null = null;
    try { stage = createStage(canvas); } catch (e) { console.warn("koipond: WebGL2 stage unavailable", e); }
    const water = stage ? null : createWater(canvas);
    if (!stage && !water) return;
    const topLayer = document.createElement("canvas"), tctx = topLayer.getContext("2d")!;
    let fish3d: ReturnType<typeof createFish3D> | null = null;
    if (stage) { try { fish3d = createFish3D(stage.renderer); } catch (e) { console.warn("koipond: 3D koi unavailable", e); } }
    let props3d: ReturnType<typeof createProps3D> | null = null;
    if (stage) { try { props3d = createProps3D(stage.renderer); } catch (e) { console.warn("koipond: 3D props unavailable", e); } }
    const scene = document.createElement("canvas"), sctx = scene.getContext("2d")!;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    let pond: Pond | null = null;

    const fit = () => {
      const r = canvas.getBoundingClientRect(), w = Math.max(1, Math.round(r.width * scale)), h = Math.max(1, Math.round(r.height * scale));
      if (stage) stage.setSize(Math.round(r.width * dpr), Math.round(r.height * dpr)); else { canvas.width = Math.round(r.width * dpr); canvas.height = Math.round(r.height * dpr); }
      scene.width = w; scene.height = h; topLayer.width = Math.round(r.width * Math.min(dpr, 1)); topLayer.height = Math.round(r.height * Math.min(dpr, 1));
      if (!pond) { pond = new Pond({ width: w, height: h, fish, fishSize, pads, petals, minnows, seed }); pond.rain = rainRef.current; pondRef.current = pond; }
      else if (w !== pond.w || h !== pond.h) pond.resize(w, h);
      sizeRef.current = { w, h };
    };
    fit();
    const ro = new ResizeObserver(fit); ro.observe(canvas);

    // pointer → pond coordinates
    const toPond = (e: PointerEvent | MouseEvent) => { const r = canvas.getBoundingClientRect(); return { x: ((e.clientX - r.left) / r.width) * pond!.w, y: ((e.clientY - r.top) / r.height) * pond!.h, inside: e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom }; };
    let press = 0, pressAt = { x: 0, y: 0 }, lastTap = 0;
    const drop: { x: number; y: number; vx: number; vy: number; tx: number; ty: number; shown: boolean; down: boolean; s?: number } = { x: 0, y: 0, vx: 0, vy: 0, tx: 0, ty: 0, shown: false, down: false };
    const onMove = (e: PointerEvent) => {
      if (!pond) return; const p = toPond(e); pond.setPointer(p.x, p.y, p.inside);
      const r = canvas.getBoundingClientRect(); drop.tx = e.clientX - r.left; drop.ty = e.clientY - r.top; drop.shown = p.inside && e.pointerType !== "touch";
    };
    const onDown = (e: PointerEvent) => {
      if (!pond) return; const p = toPond(e); if (!p.inside) return;
      const now = performance.now();
      if (now - lastTap < 320) pond.feed(p.x, p.y); else pond.splash(p.x, p.y);
      lastTap = now; press = now; pressAt = p; drop.down = true; lastTapRef.current = [p.x / pond.w, p.y / pond.h];
    };
    const onUp = () => { press = 0; drop.down = false; };
    const onAnyDown = (e: PointerEvent) => { const r = canvas.getBoundingClientRect(); lastTapRef.current = [Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)), Math.min(1, Math.max(0, (e.clientY - r.top) / r.height))]; };
    window.addEventListener("pointerdown", onAnyDown);
    if (interactive) { canvas.addEventListener("pointermove", onMove); canvas.addEventListener("pointerdown", onDown); window.addEventListener("pointerup", onUp); canvas.addEventListener("pointerleave", () => pond && pond.setPointer(pond.pointer.x, pond.pointer.y, false)); }

    // scroll becomes a current through the water; it eases off when you stop
    const flow = { x: 0, y: 0 };
    let lastTouch: { x: number; y: number } | null = null;
    const onWheel = (e: WheelEvent) => { flow.x += e.deltaX * 0.0016; flow.y += e.deltaY * 0.0016; };
    const onTouchMove = (e: TouchEvent) => { const t0 = e.touches[0]; if (!t0) return; if (lastTouch) { flow.x -= (t0.clientX - lastTouch.x) * 0.004; flow.y -= (t0.clientY - lastTouch.y) * 0.004; } lastTouch = { x: t0.clientX, y: t0.clientY }; };
    const onTouchEnd = () => { lastTouch = null; };
    if (scrollCurrent) { window.addEventListener("wheel", onWheel, { passive: true }); window.addEventListener("touchmove", onTouchMove, { passive: true }); window.addEventListener("touchend", onTouchEnd); }

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, last = performance.now(), acc = 0, visible = true;
    const manualMode = !!(window as unknown as { __koiManual?: boolean }).__koiManual;
    const io = new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && !raf && !manualMode) { last = performance.now(); raf = requestAnimationFrame(loop); } });
    io.observe(canvas);
    const loop = (now: number) => {
      raf = 0;
      if (!pond) return;
      const dt = Math.max(0, Math.min(0.1, (now - last) / 1000)); last = now; acc += dt;
      if (press && now - press > 550) { pond.feed(pressAt.x, pressAt.y); press = 0; } // long press drops food
      const el = dropRef.current;
      if (el) {
        // a ring that trails the pointer and lies flat on the water, with a small dot at the exact point
        const ease = 1 - Math.exp(-dt * 14);
        drop.x += (drop.tx - drop.x) * ease; drop.y += (drop.ty - drop.y) * ease;
        el.style.opacity = drop.shown ? "1" : "0";
        drop.s = (drop.s ?? 1) + ((drop.down ? 0.72 : 1) - (drop.s ?? 1)) * (1 - Math.exp(-dt * 18));
        const sc = drop.s;
        el.style.transform = `translate(${drop.x}px, ${drop.y}px) translate(-50%, -50%) scale(${sc})`;
        if (dotRef.current) { dotRef.current.style.opacity = drop.shown ? "1" : "0"; dotRef.current.style.transform = `translate(${drop.tx}px, ${drop.ty}px) translate(-50%, -50%)`; }
        el.style.willChange = "transform";
      }
      const fl = Math.hypot(flow.x, flow.y); if (fl > 1.6) { flow.x *= 1.6 / fl; flow.y *= 1.6 / fl; }
      flow.x *= Math.exp(-dt * 1.4); flow.y *= Math.exp(-dt * 1.4);
      if (scrollCurrent) pond.current = { x: flow.x, y: flow.y };
      pond.style = styleRef.current; pond.border = borderRef.current ? Math.min(pond.w, pond.h) * 0.06 : 0;
      while (acc >= 1 / 60) { pond.step(1 / 60); acc -= 1 / 60; }
      if (stage) {
        const cssW = Math.round(canvas.width / dpr), cssH = Math.round(canvas.height / dpr);
        drawUnder(sctx, pond, 0.8, false);
        props3d?.render(pond, cssW, cssH, pond.border > 0 ? stonesFor(pond).stones : []);
        drawTop(tctx, pond, props3d ? true : undefined);
        fish3d?.render(pond, cssW, cssH);
        stage.render({ under: scene, top: topLayer, pond, look: themeRef.current, dpr, fish: fish3d?.texture ?? null, props: props3d?.texture ?? null, origin: lastTapRef.current });
      }
      else { drawScene(sctx, pond); water!.render(scene, pond.w, pond.h, pond.ripples, pond.t, themeRef.current, dpr); }
      if (visible && !reduced) raf = requestAnimationFrame(loop);
    };
    if (reduced) { for (let i = 0; i < 120; i++) pond!.step(1 / 60); }
    // frame-exact capture (for recording videos): the page drives frames itself via window.__koiFrame(dt)
    const manual = (window as unknown as { __koiManual?: boolean }).__koiManual;
    if (manual) {
      let simNow = performance.now(); last = simNow;
      (window as unknown as { __koiFrame?: (dt: number) => void }).__koiFrame = (dt: number) => { last = simNow; simNow += dt * 1000; visible = false; loop(simNow); };
    } else raf = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(raf); ro.disconnect(); io.disconnect();
      window.removeEventListener("pointerdown", onAnyDown);
      window.removeEventListener("wheel", onWheel); window.removeEventListener("touchmove", onTouchMove); window.removeEventListener("touchend", onTouchEnd);
      canvas.removeEventListener("pointermove", onMove); canvas.removeEventListener("pointerdown", onDown); window.removeEventListener("pointerup", onUp);
      pondRef.current = null; fish3d?.dispose(); props3d?.dispose(); stage?.dispose();
    };
  }, [minnows, seed, interactive, scale, scrollCurrent]); // eslint-disable-line react-hooks/exhaustive-deps

  // live settings: the pond eases into the new values instead of being rebuilt
  useEffect(() => { pondRef.current?.setFishCount(fish); }, [fish]);
  useEffect(() => { pondRef.current?.setFishSize(fishSize); }, [fishSize]);
  useEffect(() => { pondRef.current?.setPadCount(pads); }, [pads]);
  useEffect(() => { pondRef.current?.setPetalCount(petals); }, [petals]);

  return (
    <div className={className} style={{ position: "relative", overflow: "hidden", width: "100%", height: "100%", ...style }}>
      <canvas ref={canvasRef} style={{ display: "block", width: "100%", height: "100%", touchAction: "manipulation", cursor: cursor && interactive ? "none" : undefined }} />
      {cursor && interactive && (
        <>
          <div ref={dropRef} aria-hidden style={{ position: "absolute", left: 0, top: 0, width: 30, height: 30, borderRadius: "50%", pointerEvents: "none", opacity: 0, transition: "opacity .3s", border: "1.5px solid rgba(255,255,255,.7)", willChange: "transform", boxShadow: "0 0 12px rgba(255,255,255,.12)" }} />
          <div ref={dotRef} aria-hidden style={{ position: "absolute", left: 0, top: 0, width: 5, height: 5, borderRadius: "50%", pointerEvents: "none", opacity: 0, transition: "opacity .3s", background: "rgba(255,255,255,.95)", boxShadow: "0 0 6px rgba(255,255,255,.6)" }} />
        </>
      )}
    </div>
  );
});

// koipond — the simulation. Pure TypeScript, no DOM. Units are pond pixels.
//
// How a fish works here:
//   • Mood: every fish has a temperament (bold ↔ shy, lazy ↔ restless) that shapes all its choices.
//   • Intent: a small set of activities (drift, cruise, dart, rest, investigate, feed, flee), chosen by
//     weighted chance from its mood and what is happening around it, each lasting a while.
//   • Steering: the activity sets a goal heading and speed; neighbours, walls and the water current
//     bend that goal. The fish turns toward it with limited, speed-dependent turning (a heavy body).
//   • Body: a chain of joints pulled along by the head, with a cap on how sharply any joint can bend,
//     so the body curves through turns but can never kink or fold. A muscle wave travels nose → tail
//     with an amplitude that rises toward the tail and with how hard the fish is swimming.
//   • Tail fin: its own short chain on springs, so it trails and flicks after the body (follow-through).

export type V = { x: number; y: number };
const TAU = Math.PI * 2;
const angleDiff = (a: number, b: number) => Math.atan2(Math.sin(a - b), Math.cos(a - b));
const clamp = (v: number, lo: number, hi: number) => (v < lo ? lo : v > hi ? hi : v);
const len = (x: number, y: number) => Math.sqrt(x * x + y * y);

export class Random {
  private s: number;
  constructor(seed = 1) { this.s = seed >>> 0 || 1; }
  /** mulberry32 */
  next() { let t = (this.s = (this.s + 0x6d2b79f5) >>> 0); t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
  between(a: number, b: number) { return a + (b - a) * this.next(); }
  pick<T>(xs: readonly T[]) { return xs[Math.floor(this.next() * xs.length)]; }
}

export type Activity = "drift" | "cruise" | "dart" | "rest" | "investigate" | "feed" | "flee";

export interface Variety { name: string; base: string; spots: string[]; fin: string; spotCover: number }
export const MINNOW: Variety = { name: "minnow", base: "#4c5a55", spots: [], fin: "#7c8c86", spotCover: 0 };
export const VARIETIES: Variety[] = [
  // the palette of the reference pond: vivid orange-red on cream, a few with sumi black, warm orange and gold
  { name: "kohaku", base: "#f2ebdf", spots: ["#e04a1f"], fin: "#f2ebdf", spotCover: 0.85 },
  { name: "sanke", base: "#f2ebdf", spots: ["#e04a1f", "#e04a1f", "#1c1a1e"], fin: "#f2ebdf", spotCover: 0.8 },
  { name: "yamabuki", base: "#ec7a2a", spots: ["#f2ebdf"], fin: "#f3c79a", spotCover: 0.25 },
  { name: "kohaku", base: "#f2ebdf", spots: ["#e8642a"], fin: "#f2ebdf", spotCover: 0.95 },
  { name: "ogon", base: "#eaa53c", spots: ["#f2ebdf"], fin: "#f2cf8a", spotCover: 0.12 },
  { name: "tancho", base: "#f2ebdf", spots: [], fin: "#f2ebdf", spotCover: 0 },
  { name: "sanke", base: "#f2ebdf", spots: ["#d94420", "#1c1a1e"], fin: "#f2ebdf", spotCover: 0.75 },
  { name: "showa", base: "#1c1a1e", spots: ["#e04a1f", "#f2ebdf"], fin: "#d9d3cc", spotCover: 0.7 },
];

/** A spot on the body, in body coordinates: u along the body (0 nose, 1 tail root), v across (-1..1). */
export interface Spot { u: number; v: number; ru: number; rv: number; color: string }

export interface Fish {
  id: number; variety: Variety; spots: Spot[];
  length: number; girth: number;              // body length, max half-width
  bold: number; restless: number;             // temperament 0..1
  x: number; y: number; heading: number; speed: number; turn: number;
  activity: Activity; activityLeft: number; goalHeading: number; goalSpeed: number; target: V | null;
  effort: number; beat: number;               // swim effort 0..1+, muscle wave phase
  depth: number; depthGoal: number;           // 0 surface .. 1 deep
  joints: V[]; tail: V[]; tailVel: V[];
  finPhase: number; lastGulp: number;
  /** 0..1 how present the fish is (grows in when added, shrinks away when removed); body ratios for live resizing. */
  presence: number; leaving: boolean; lenRatio: number; girthRatio: number;
}

export interface Bubble { x: number; y: number; r: number; age: number; life: number }
export interface Spark { x: number; y: number; vx: number; vy: number; age: number; life: number; r: number; drip?: boolean }
export interface Pellet { x: number; y: number; vx: number; vy: number; age: number; eaten: boolean }
export interface Ripple { x: number; y: number; age: number; power: number; kind: "tap" | "drop" | "nibble" | "wake" }
export interface Pad { x: number; y: number; r: number; spin: number; angle: number; vx: number; vy: number; notch: number; tone: number; flower: boolean; hx: number; hy: number; rRatio: number; presence: number; leaving: boolean }
export interface Petal { x: number; y: number; r: number; spin: number; angle: number; vx: number; vy: number; z: number }
export interface Weed { x: number; y: number; len: number; phase: number; dir: number }

export interface PondOptions {
  width: number; height: number; fish?: number; seed?: number;
  /** Size of the fish relative to the pond's short side (default 0.11). */
  fishSize?: number;
  pads?: number;
  /** Floating blossom petals (or leaves). */
  petals?: number;
  /** A small school of tiny dark fish. */
  minnows?: number;
  /** Rectangles (pond pixels) fish prefer to stay out of, e.g. behind a headline. */
  keepClear?: { x: number; y: number; w: number; h: number }[];
}

const JOINTS = 16, TAIL = 4;

export class Pond {
  w: number; h: number; t = 0;
  fish: Fish[] = []; sparks: Spark[] = []; flashes: { x: number; y: number; age: number }[] = []; bubbles: Bubble[] = []; pellets: Pellet[] = []; ripples: Ripple[] = []; pads: Pad[] = []; petals: Petal[] = []; weeds: Weed[] = [];
  private petalMax = 0; private nextPetal = 0;
  current: V = { x: 0, y: 0 };
  /** Width of the stone border around the pond (pond pixels); 0 = no border. */
  border = 0;
  /** How far a point is toward the shore: 0 at the centre, 1 on the water line (pond shape = rounded, slightly irregular). */
  shore(x: number, y: number) {
    // only a small stone cluster in the lower-left corner: fish and floaters keep off it
    if (this.border <= 0) return 0;
    const r = this.border * 4.2, d = len(x - 0, y - this.h);
    return d < r ? 1.2 - d / r * 0.4 : 0;
  }
  private shoreUnused(x: number, y: number) {
    if (this.border <= 0) return 0;
    const a = this.w / 2 - this.border * 1.1, b = this.h / 2 - this.border * 1.1, dx = (x - this.w / 2) / a, dy = (y - this.h / 2) / b;
    const ang = Math.atan2(dy, dx), wob = 1 + 0.035 * Math.sin(ang * 3 + 1.3) + 0.025 * Math.sin(ang * 5 + 0.4);
    return Math.pow(Math.pow(Math.abs(dx), 3.2) + Math.pow(Math.abs(dy), 3.2), 1 / 3.2) / wob;
  }
  /** Which art style the pond is drawn in (drawing reads this for its colours). */
  style = "natural";
  /** 0..1: how hard it is raining. */
  rain = 0;
  private lastWake: V = { x: -1e9, y: -1e9 };
  pointer: { x: number; y: number; still: number; speed: number; inside: boolean } = { x: 0, y: 0, still: 0, speed: 0, inside: false };
  keepClear: NonNullable<PondOptions["keepClear"]>;
  private rnd: Random;
  private nextId = 0;
  private unit: number;
  private nextDrop = 2;
  private formation: { slots: V[]; flow: V[]; owner: number[] } | null = null;

  constructor(o: PondOptions) {
    this.w = o.width; this.h = o.height; this.rnd = new Random(o.seed ?? 7);
    this.unit = Math.min(o.width, o.height) * (o.fishSize ?? 0.14);
    this.keepClear = o.keepClear ?? [];
    for (let i = 0; i < (o.fish ?? 9); i++) this.fish.push(this.makeFish(i));
    for (let i = 0; i < (o.minnows ?? 0); i++) {
      const m = this.makeFish(1000 + i);
      m.variety = MINNOW; m.spots = []; m.lenRatio = this.rnd.between(0.24, 0.32); m.girthRatio = 0.13; m.length = this.unit * m.lenRatio; m.girth = m.length * 0.13;
      m.bold = 0.1; m.restless = 0.95; m.depth = this.rnd.between(0.3, 0.6);
      const seg = m.length / (JOINTS - 1); m.joints.forEach((j, k) => { j.x = m.x - Math.cos(m.heading) * seg * k; j.y = m.y - Math.sin(m.heading) * seg * k; });
      m.tail.forEach((j, k) => { j.x = m.x - Math.cos(m.heading) * (m.length + seg * 0.8 * (k + 1)); j.y = m.y - Math.sin(m.heading) * (m.length + seg * 0.8 * (k + 1)); });
      this.fish.push(m);
    }
    for (let i = 0; i < (o.pads ?? 3); i++) { const pad = this.makePad(); if (i === 0) { pad.flower = true; pad.tone = 0.3; } this.pads.push(pad); }
    this.petalMax = o.petals ?? 9;
    for (let i = 0; i < this.petalMax; i++) this.petals.push(this.makePetal(0));
    // water plants rooted on the floor, in loose clumps
    for (let c = 0; c < 4; c++) { const cx = this.rnd.between(0.05, 0.95) * this.w, cy = this.rnd.between(0.05, 0.95) * this.h;
      for (let k = 0; k < 9; k++) this.weeds.push({ x: cx + this.rnd.between(-1, 1) * this.unit * 0.25, y: cy + this.rnd.between(-1, 1) * this.unit * 0.25, len: this.unit * this.rnd.between(0.5, 1.1), phase: this.rnd.between(0, TAU), dir: this.rnd.between(0, TAU) }); }
  }

  private makeFish(id: number): Fish {
    const r = this.rnd, variety = VARIETIES[id % VARIETIES.length];
    const lenRatio = r.between(0.78, 1.25), length = this.unit * lenRatio, girthRatio = r.between(0.1, 0.12), girth = length * girthRatio;
    const x = r.between(0.1, 0.9) * this.w, y = r.between(0.12, 0.88) * this.h, heading = r.between(-Math.PI, Math.PI);
    const joints: V[] = [], seg = length / (JOINTS - 1);
    for (let i = 0; i < JOINTS; i++) joints.push({ x: x - Math.cos(heading) * seg * i, y: y - Math.sin(heading) * seg * i });
    const last = joints[JOINTS - 1], tail: V[] = [], tailVel: V[] = [];
    for (let i = 1; i <= TAIL; i++) { tail.push({ x: last.x - Math.cos(heading) * seg * 0.8 * i, y: last.y - Math.sin(heading) * seg * 0.8 * i }); tailVel.push({ x: 0, y: 0 }); }
    // spots: a few soft blobs; tancho gets its single red crown
    const spots: Spot[] = [];
    if (variety.name === "tancho") spots.push({ u: 0.07, v: 0, ru: 0.055, rv: 0.55, color: "#dc4f26" });
    let cover = 0;
    while (cover < variety.spotCover) {
      const ru = r.between(0.06, 0.15), rv = r.between(0.4, 0.95);
      const u0 = r.between(0.05, 0.85), v0 = r.between(-0.5, 0.5), color = r.pick(variety.spots);
      spots.push({ u: u0, v: v0, ru, rv, color });
      for (let k = 0; k < 2; k++) spots.push({ u: u0 + r.between(-ru, ru) * 0.8, v: v0 + r.between(-0.35, 0.35), ru: ru * r.between(0.45, 0.75), rv: rv * r.between(0.5, 0.85), color });
      cover += ru * rv * 1.1;
    }
    return {
      id, variety, spots, length, girth, bold: r.next(), restless: r.next(),
      x, y, heading, speed: 0, turn: 0, activity: "drift", activityLeft: r.between(0.5, 3), goalHeading: heading, goalSpeed: 0, target: null,
      effort: 0.3, beat: r.between(0, TAU), depth: r.between(0.1, 0.6), depthGoal: 0.3, joints, tail, tailVel, finPhase: r.between(0, TAU), lastGulp: -99, presence: 1, leaving: false, lenRatio, girthRatio,
    };
  }

  private makePetal(z: number): Petal {
    const r = this.rnd;
    return { x: r.between(0, 1) * this.w, y: r.between(0, 1) * this.h, r: this.unit * r.between(0.055, 0.085), spin: r.between(-0.6, 0.6), angle: r.between(0, TAU), vx: 0, vy: 0, z };
  }

  private makePad(): Pad {
    const r = this.rnd;
    // each pad has a home inside the frame it drifts back to, so it never wanders off screen for long
    const hx = r.between(0.04, 0.96) * this.w, hy = r.between(0.06, 0.94) * this.h, rr = r.between(0.42, 0.68);
    return { x: hx, y: hy, r: this.unit * rr, spin: r.between(-0.03, 0.03), angle: r.between(0, TAU), vx: 0, vy: 0, notch: r.between(0.3, 0.5), tone: r.next(), flower: r.next() < 0.45, hx, hy, rRatio: rr, presence: 1, leaving: false };
  }

  // ------------------------------------------------------------------------------------- events
  /** A tap lands: a crown of droplets thrown out, a brief flash, and the ring. */
  splash(x: number, y: number) {
    const u = this.unit;
    for (let i = 0; i < 14; i++) { const a = (i / 14) * TAU + this.rnd.between(-0.2, 0.2), sp = u * this.rnd.between(0.5, 1.1); this.sparks.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, age: -this.rnd.between(0, 0.04), life: this.rnd.between(0.32, 0.5), r: u * this.rnd.between(0.02, 0.03), drip: true }); }
    this.flashes.push({ x, y, age: 0 });
    if (this.sparks.length > 400) this.sparks.splice(0, this.sparks.length - 400);
    this.ripple(x, y, "tap", 1);
  }

  ripple(x: number, y: number, kind: Ripple["kind"] = "tap", power = 1) {
    const rings = kind === "tap" ? 3 : 1;
    for (let i = 0; i < rings; i++) this.ripples.push({ x, y, age: -i * 0.09, power: power * (1 - i * 0.22), kind });
    if (this.ripples.length > 48) this.ripples.splice(0, this.ripples.length - 48);
    // a ripple pushes floating pads and startles shy fish nearby
    for (const p of this.pads) { const dx = p.x - x, dy = p.y - y, d = len(dx, dy) || 1; if (d < this.unit * 2.2) { const f = (1 - d / (this.unit * 2.2)) * this.unit * 0.6 * power; p.vx += dx / d * f; p.vy += dy / d * f; } }
    for (const p of this.petals) { const dx = p.x - x, dy = p.y - y, d = len(dx, dy) || 1; if (d < this.unit * 2.5) { const f = (1 - d / (this.unit * 2.5)) * this.unit * 1.4 * power; p.vx += dx / d * f; p.vy += dy / d * f; p.spin += (this.rnd.next() - 0.5) * 1.5 * power; } }
    if (kind === "tap") for (const f of this.fish) { const d = len(f.x - x, f.y - y); if (d < this.unit * 1.6 && f.bold < 0.45) this.setActivity(f, "flee", 0.9, { x, y }); }
  }

  /** Scatter a few food pellets around a point; nearby fish come to feed. */
  feed(x: number, y: number, n = 5) {
    for (let i = 0; i < n; i++) { const a = this.rnd.between(0, TAU), s = this.rnd.between(4, 22); this.pellets.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, age: 0, eaten: false }); }
    if (this.pellets.length > 40) this.pellets.splice(0, this.pellets.length - 40);
    this.ripple(x, y, "drop", 0.8);
  }

  setPointer(x: number, y: number, inside: boolean) {
    const p = this.pointer, moved = len(x - p.x, y - p.y);
    p.speed = p.speed * 0.6 + moved * 0.4; p.x = x; p.y = y; p.inside = inside;
    if (moved > 0.5) p.still = 0;
    // a finger moving through the water drags a wake behind it
    if (inside && len(x - this.lastWake.x, y - this.lastWake.y) > this.unit * 0.06) {
      const d = len(x - this.lastWake.x, y - this.lastWake.y), fresh = this.lastWake.x < -1e8 || d > this.unit * 3;
      if (!fresh) {
        const steps = Math.min(4, Math.ceil(d / (this.unit * 0.08))), power = Math.min(1, 0.35 + d / (this.unit * 0.3));
        for (let q = 1; q <= steps; q++) this.ripple(this.lastWake.x + (x - this.lastWake.x) * q / steps, this.lastWake.y + (y - this.lastWake.y) * q / steps, "wake", power);
        // a few points of light peel away to either side, like a boat's wake
        const nx = -(y - this.lastWake.y) / d, ny = (x - this.lastWake.x) / d;
        for (const side of [1, -1]) this.sparks.push({ x, y, vx: nx * side * this.unit * 0.25, vy: ny * side * this.unit * 0.25, age: 0, life: 0.6, r: this.unit * 0.012 });
      }
      this.lastWake = { x, y };
    }
    if (!inside) this.lastWake = { x: -1e9, y: -1e9 };
  }

  /** Ask the fish to hold a shape: a slot for each fish and the direction to swim through it. */
  setFormation(slots: V[] | null, flow?: V[]) {
    if (!slots) { if (this.formation) for (const f of this.fish) this.setActivity(f, this.rnd.next() < 0.5 ? "dart" : "cruise"); this.formation = null; return; }
    if (!this.formation) {
      const free = slots.map((_, i) => i), owner: number[] = [];
      for (const f of this.fish) {
        if (!free.length) { owner.push(-1); continue; }
        let best = 0, bd = Infinity;
        free.forEach((s, k) => { const d = len(slots[s].x - f.x, slots[s].y - f.y); if (d < bd) { bd = d; best = k; } });
        owner.push(free.splice(best, 1)[0]);
      }
      this.formation = { slots, flow: flow ?? slots.map(() => ({ x: 1, y: 0 })), owner };
    } else { this.formation.slots = slots; if (flow) this.formation.flow = flow; }
  }

  /** Change the pond while it lives: koi, size, pads and petals ease in or out instead of resetting. */
  setFishSize(fishSize: number) { this.unit = Math.min(this.w, this.h) * fishSize; }
  setFishCount(n: number) {
    const koi = this.fish.filter((f) => f.variety !== MINNOW && !f.leaving);
    if (koi.length < n) {
      for (let i = koi.length; i < n; i++) {
        const id = 2000 + (this.nextId++), f = this.makeFish(id);
        f.presence = 0; f.depth = 0.9; f.depthGoal = 0.3; // rises up from the deep
        this.fish.push(f);
      }
    } else for (const f of koi.slice(n)) { f.leaving = true; f.depthGoal = 1; }
  }
  setPadCount(n: number) {
    const live = this.pads.filter((p) => !p.leaving);
    if (live.length < n) for (let i = live.length; i < n; i++) { const p = this.makePad(); p.presence = 0; p.r = 0.01; this.pads.push(p); }
    else for (const p of live.slice(n)) p.leaving = true;
  }
  setPetalCount(n: number) { this.petalMax = n; if (n === 0) for (const p of this.petals) p.z = Math.min(p.z, 0); }

  resize(w: number, h: number) {
    const sx = w / this.w, sy = h / this.h;
    for (const f of this.fish) { f.x *= sx; f.y *= sy; for (const j of [...f.joints, ...f.tail]) { j.x *= sx; j.y *= sy; } }
    for (const p of [...this.pads, ...this.petals]) { p.x *= sx; p.y *= sy; }
    this.w = w; this.h = h;
  }

  // ---------------------------------------------------------------------------------- behaviour
  private setActivity(f: Fish, a: Activity, seconds?: number, target: V | null = null) {
    f.activity = a; f.target = target;
    const span: Record<Activity, [number, number]> = { drift: [2, 6], cruise: [2.5, 7], dart: [0.35, 0.8], rest: [1.2, 4], investigate: [2, 5], feed: [3, 8], flee: [0.6, 1.2] };
    f.activityLeft = seconds ?? this.rnd.between(span[a][0], span[a][1]) * (a === "rest" ? 1.4 - f.restless : 1);
    if (a === "dart") f.goalHeading = f.heading + this.rnd.between(-0.9, 0.9);
  }

  private choose(f: Fish) {
    // food first, then curiosity about a still pointer, otherwise mood decides
    const pellet = this.nearestPellet(f, this.unit * 4);
    if (pellet) return this.setActivity(f, "feed", undefined, pellet);
    const p = this.pointer;
    if (p.inside && p.still > 1.2 && len(p.x - f.x, p.y - f.y) < this.unit * 3.5 && this.rnd.next() < 0.35 + f.bold * 0.5) return this.setActivity(f, "investigate", undefined, { x: p.x, y: p.y });
    const r = this.rnd.next(), rest = 0.18 * (1 - f.restless), dart = 0.08 + 0.12 * f.restless, cruise = 0.32 + 0.2 * f.restless;
    this.setActivity(f, r < rest ? "rest" : r < rest + dart ? "dart" : r < rest + dart + cruise ? "cruise" : "drift");
  }

  private nearestPellet(f: Fish, within: number): Pellet | null {
    let best: Pellet | null = null, bd = within;
    for (const p of this.pellets) { if (p.eaten) continue; const d = len(p.x - f.x, p.y - f.y); if (d < bd) { bd = d; best = p; } }
    return best;
  }

  step(dt: number) {
    this.t += dt;
    const u = this.unit, ptr = this.pointer;
    ptr.still += dt; ptr.speed *= Math.exp(-dt * 6);

    // ambient life: an occasional drop on the surface
    this.nextDrop -= dt;
    while (this.nextDrop < 0) { this.ripple(this.rnd.between(0, this.w), this.rnd.between(0, this.h), "drop", 0.55 + this.rain * 0.3); this.nextDrop += this.rnd.between(2.5, 6) / (1 + this.rain * 40); }

    // bubbles: now and then a koi breathes out a few; they surface, sit a moment, and pop
    for (const f of this.fish) if (f.variety !== MINNOW && this.rnd.next() < dt * 0.12) {
      const n = 1 + Math.floor(this.rnd.next() * 3);
      for (let k = 0; k < n; k++) this.bubbles.push({ x: f.x + this.rnd.between(-1, 1) * f.girth, y: f.y + this.rnd.between(-1, 1) * f.girth, r: u * this.rnd.between(0.025, 0.05), age: -k * 0.25, life: this.rnd.between(1.5, 3.5) });
    }
    for (const b of this.bubbles) { b.age += dt; b.x += this.current.x * u * 0.2 * dt; b.y += this.current.y * u * 0.2 * dt; if (b.age > b.life) this.ripple(b.x, b.y, "nibble", 0.25); }
    this.bubbles = this.bubbles.filter((b) => b.age <= b.life).slice(-60);
    for (const sp of this.sparks) { sp.age += dt; if (sp.age > 0) { sp.x += sp.vx * dt; sp.y += sp.vy * dt; sp.vx *= Math.exp(-dt * 3); sp.vy *= Math.exp(-dt * 3); } }
    for (const sp of this.sparks) if (sp.drip && sp.age >= sp.life) this.ripple(sp.x, sp.y, "nibble", 0.35);
    this.sparks = this.sparks.filter((sp) => sp.age < sp.life);
    for (const fl of this.flashes) fl.age += dt;
    this.flashes = this.flashes.filter((fl) => fl.age < 0.3);
    for (const r of this.ripples) r.age += dt;
    this.ripples = this.ripples.filter((r) => r.age < (r.kind === "tap" ? 2.6 : r.kind === "drop" ? 1.6 : 1.0));

    for (const p of this.pellets) { p.age += dt; p.x += p.vx * dt + this.current.x * 6 * dt; p.y += p.vy * dt + this.current.y * 6 * dt; p.vx *= Math.exp(-dt * 2.5); p.vy *= Math.exp(-dt * 2.5); }
    this.pellets = this.pellets.filter((p) => !p.eaten && p.age < 40);

    for (const p of this.pads) {
      p.vx += (this.current.x * u * 0.9 - p.vx) * dt * 1.2; p.vy += (this.current.y * u * 0.9 - p.vy) * dt * 1.2;
      p.vx *= Math.exp(-dt * 0.8); p.vy *= Math.exp(-dt * 0.8);
      p.x += p.vx * dt + Math.sin(this.t * 0.1 + p.angle) * u * 0.02 * dt; p.y += p.vy * dt + Math.cos(this.t * 0.08 + p.angle) * u * 0.02 * dt;
      p.angle += p.spin * dt;
      // a gentle pull back toward home, and a soft bounce off the frame edges
      p.vx += (p.hx - p.x) * dt * 0.05; p.vy += (p.hy - p.y) * dt * 0.05;
      const m = 0; // a pad may drift half off the edge before it turns back
      if (p.x < m) { p.x = m; p.vx = Math.abs(p.vx) * 0.5; } if (p.x > this.w - m) { p.x = this.w - m; p.vx = -Math.abs(p.vx) * 0.5; }
      if (p.y < m) { p.y = m; p.vy = Math.abs(p.vy) * 0.5; } if (p.y > this.h - m) { p.y = this.h - m; p.vy = -Math.abs(p.vy) * 0.5; }
      p.presence += ((p.leaving ? 0 : 1) - p.presence) * (1 - Math.exp(-dt * 2.5));
      p.r += (this.unit * p.rRatio * Math.max(0.01, p.presence) - p.r) * (1 - Math.exp(-dt * 3));
      if (this.border > 0 && !((p as unknown as { z?: number }).z! > 0) && this.shore(p.x, p.y) > 0.9) { const cx = this.w / 2 - p.x, cy = this.h / 2 - p.y, d = len(cx, cy) || 1; p.vx = cx / d * this.unit * 0.15; p.vy = cy / d * this.unit * 0.15; p.x += cx / d * 1.5; p.y += cy / d * 1.5; }
      if (false) { const b = this.border + p.r; if (p.x < b) { p.x = b; p.vx = Math.abs(p.vx); } if (p.x > this.w - b) { p.x = this.w - b; p.vx = -Math.abs(p.vx); } if (p.y < b) { p.y = b; p.vy = Math.abs(p.vy); } if (p.y > this.h - b) { p.y = this.h - b; p.vy = -Math.abs(p.vy); } }
    }

    // sakura: every so often a petal drifts down from above and settles on the water
    this.nextPetal -= dt;
    if (this.petalMax > 0 && this.nextPetal < 0) {
      this.petals.push(this.makePetal(1)); this.nextPetal = this.rnd.between(0.7, 1.8);
      const floating = this.petals.filter((q) => q.z <= 0);
      if (floating.length > this.petalMax * 2) this.petals.splice(this.petals.indexOf(floating[0]), 1);
    }
    for (const p of this.petals) {
      if (p.z > 0) {
        p.z -= dt * 0.28; p.angle += dt * 2.2 * Math.sign(p.spin || 1);
        p.x += Math.sin(this.t * 1.7 + p.r * 50) * u * 0.25 * dt + u * 0.12 * dt; p.y += u * 0.08 * dt;
        if (p.z <= 0) { p.z = 0; this.ripple(p.x, p.y, "nibble", 0.3); }
        continue;
      }
      p.vx += (this.current.x * u * 1.4 + Math.sin(this.t * 0.13 + p.angle) * u * 0.03 - p.vx) * dt * 0.5;
      p.vy += (this.current.y * u * 1.4 + Math.cos(this.t * 0.11 + p.r) * u * 0.03 - p.vy) * dt * 0.5;
      p.x += p.vx * dt; p.y += p.vy * dt; p.angle += p.spin * dt; p.spin *= Math.exp(-dt * 0.6);
      const m = p.r * 2; if (p.x < -m) p.x = this.w + m; if (p.x > this.w + m) p.x = -m; if (p.y < -m) p.y = this.h + m; if (p.y > this.h + m) p.y = -m;
      if (this.border > 0 && !((p as unknown as { z?: number }).z! > 0) && this.shore(p.x, p.y) > 0.9) { const cx = this.w / 2 - p.x, cy = this.h / 2 - p.y, d = len(cx, cy) || 1; p.vx = cx / d * this.unit * 0.15; p.vy = cy / d * this.unit * 0.15; p.x += cx / d * 1.5; p.y += cy / d * 1.5; }
      if (false) { const b = this.border + p.r; if (p.x < b) { p.x = b; p.vx = Math.abs(p.vx); } if (p.x > this.w - b) { p.x = this.w - b; p.vx = -Math.abs(p.vx); } if (p.y < b) { p.y = b; p.vy = Math.abs(p.vy); } if (p.y > this.h - b) { p.y = this.h - b; p.vy = -Math.abs(p.vy); } }
    }
    // koi ease toward their size; arriving koi grow in, leaving koi sink and shrink away
    for (const f of this.fish) {
      f.presence += ((f.leaving ? 0 : 1) - f.presence) * (1 - Math.exp(-dt * 1.6));
      const L = this.unit * f.lenRatio * (0.25 + 0.75 * f.presence);
      f.length += (L - f.length) * (1 - Math.exp(-dt * 3)); f.girth = f.length * f.girthRatio * (0.4 + 0.6 * f.presence);
    }
    this.fish = this.fish.filter((f) => !(f.leaving && f.presence < 0.04));
    this.pads = this.pads.filter((p) => !(p.leaving && p.presence < 0.04));
    if (this.petalMax === 0) this.petals = this.petals.filter((p) => p.z > 0 ? false : (p.r *= 0.97) > this.unit * 0.01);
    const fm = this.formation;
    this.fish.forEach((f, idx) => {
      f.activityLeft -= dt;
      const slot = fm && fm.owner[idx] >= 0 ? fm.slots[fm.owner[idx]] : null;

      // a fast pointer close by is a threat; a still one is interesting
      const pd = len(ptr.x - f.x, ptr.y - f.y);
      if (ptr.inside && ptr.speed > u * 0.4 && pd < u * (0.6 + 0.5 * (1 - f.bold)) && f.activity !== "flee" && !slot) this.setActivity(f, "flee", 0.6, { x: ptr.x, y: ptr.y });
      if (f.activityLeft <= 0 && !slot) this.choose(f);
      if (f.activity === "feed" && (!f.target || (f.target as Pellet).eaten)) this.choose(f);

      // ----- what does it want?
      let gx = Math.cos(f.heading), gy = Math.sin(f.heading), want = 0;
      const wander = Math.sin(this.t * (0.21 + f.restless * 0.2) + f.id * 3.1) * 0.6 + Math.sin(this.t * 0.07 + f.id) * 0.4;
      switch (f.activity) {
        case "drift": gx = Math.cos(f.heading + wander * 0.9); gy = Math.sin(f.heading + wander * 0.9); want = u * 0.32; break;
        case "cruise": gx = Math.cos(f.heading + wander * 0.5); gy = Math.sin(f.heading + wander * 0.5); want = u * (0.55 + f.restless * 0.25); break;
        case "dart": gx = Math.cos(f.goalHeading); gy = Math.sin(f.goalHeading); want = u * 2.1; break;
        case "rest": want = u * 0.04; break;
        case "investigate": case "feed": {
          const tg = f.target!; const dx = tg.x - f.x, dy = tg.y - f.y, d = len(dx, dy) || 1;
          gx = dx / d; gy = dy / d; want = clamp(d * 0.9, u * 0.1, u * (f.activity === "feed" ? 1.3 : 0.6));
          if (f.activity === "feed" && d < f.girth * 1.6) { (tg as Pellet).eaten = true; this.ripple(tg.x, tg.y, "nibble", 0.7); f.lastGulp = this.t; this.setActivity(f, "drift", 1.2); }
          if (f.activity === "investigate" && d < f.length * 0.55) { want = 0; if (this.t - f.lastGulp > 2.5 && this.rnd.next() < dt * 0.8) { this.ripple(f.x + gx * f.girth, f.y + gy * f.girth, "nibble", 0.5); f.lastGulp = this.t; } }
          break;
        }
        case "flee": { const tg = f.target!; const dx = f.x - tg.x, dy = f.y - tg.y, d = len(dx, dy) || 1; gx = dx / d; gy = dy / d; want = u * 2.6; break; }
      }
      if (slot) {
        const dx = slot.x - f.x, dy = slot.y - f.y, d = len(dx, dy) || 1, fl = fm!.flow[fm!.owner[idx]];
        const arrive = clamp(d / (f.length * 1.2), 0, 1);
        gx = dx / d * arrive + fl.x * (1 - arrive); gy = dy / d * arrive + fl.y * (1 - arrive);
        want = clamp(d * 1.8, u * 0.45, u * 2.4);
      }

      // ----- the world bends the wish: neighbours, walls, keep-clear areas, current
      let ax = 0, ay = 0;
      for (const o of this.fish) {
        if (o === f) continue;
        // keep clear of the other fish's whole body (sampled joints), not just its head
        for (let j = 0; j < JOINTS; j += 5) {
          const dx = f.x - o.joints[j].x, dy = f.y - o.joints[j].y, d = len(dx, dy), R = (f.length + o.length) * 0.32;
          if (d > 0 && d < R) { const k = (1 - d / R) ** 2 * 3; ax += dx / d * k; ay += dy / d * k; }
        }
        if (!slot && f.activity !== "flee") { const d = len(o.x - f.x, o.y - f.y); if (d < u * 2.2) { const k = (1 - d / (u * 2.2)) * 0.18; ax += Math.cos(o.heading) * k; ay += Math.sin(o.heading) * k; } }
      }
      const look = f.length * (0.8 + f.speed / (u * 2)), lx = f.x + Math.cos(f.heading) * look, ly = f.y + Math.sin(f.heading) * look, m = u * 0.45;
      if (this.border > 0) { const v = this.shore(lx, ly); if (v > 0.82) { const cx = this.w / 2 - f.x, cy = this.h / 2 - f.y, d = len(cx, cy) || 1, k = (v - 0.82) * 14; ax += cx / d * k; ay += cy / d * k; } }
      const m2 = u * 0.45; if (lx < m2) ax += (m2 - lx) / m2 * 2.5; if (lx > this.w - m) ax -= (lx - (this.w - m)) / m * 2.5;
      if (ly < m) ay += (m - ly) / m * 2.5; if (ly > this.h - m) ay -= (ly - (this.h - m)) / m * 2.5;
      if (!slot) for (const z of this.keepClear) {
        if (lx > z.x && lx < z.x + z.w && ly > z.y && ly < z.y + z.h) { const cx = z.x + z.w / 2, cy = z.y + z.h / 2, dx = f.x - cx, dy = (f.y - cy) * (z.w / Math.max(1, z.h)), d = len(dx, dy) || 1; ax += dx / d * 1.4; ay += dy / d * 1.4; }
      }
      gx += ax + this.current.x * 2.6; gy += ay + this.current.y * 2.6;
      want += len(this.current.x, this.current.y) * u * 1.6;
      f.goalSpeed = want;

      // ----- heavy body: turning is limited, faster when moving, sharper in a dart
      const goal = Math.atan2(gy, gx), err = angleDiff(goal, f.heading);
      const agility = (0.9 + 2.4 * clamp(f.speed / (u * 1.2), 0, 1)) * (f.activity === "dart" || f.activity === "flee" ? 1.6 : 1);
      f.turn += (clamp(err * 3, -agility, agility) - f.turn) * (1 - Math.exp(-dt * 6));
      f.heading += f.turn * dt;
      const accel = f.goalSpeed > f.speed ? (f.activity === "dart" || f.activity === "flee" ? 7 : 1.6) : 1.1;
      f.speed += (f.goalSpeed - f.speed) * (1 - Math.exp(-dt * accel));
      f.x += Math.cos(f.heading) * f.speed * dt; f.y += Math.sin(f.heading) * f.speed * dt;

      // swim effort: thrust when speeding up or turning hard, near-still tail while gliding
      const thrust = clamp((f.goalSpeed - f.speed) / (u * 0.6), 0, 1) + Math.abs(f.turn) * 0.25 + f.speed / (u * 3);
      f.effort += (clamp(thrust, 0.06, 1.3) - f.effort) * (1 - Math.exp(-dt * 3));
      f.beat += dt * (1.2 + f.effort * 7.5);
      f.finPhase += dt * (1.4 + (f.activity === "rest" || f.activity === "investigate" ? 2.2 : 0));

      // depth drifts slowly; feeding and curiosity bring a fish up to the surface
      if (this.rnd.next() < dt * 0.06) f.depthGoal = this.rnd.next() < 0.3 ? this.rnd.between(0.55, 0.85) : this.rnd.between(0.05, 0.35);
      const goalDepth = f.activity === "feed" || f.activity === "investigate" || slot ? 0.05 : f.depthGoal;
      f.depth += (goalDepth - f.depth) * (1 - Math.exp(-dt * 0.4));

      // a fast fish close to the surface leaves a faint wake
      if (f.depth < 0.25 && f.speed > u * 1.4 && this.rnd.next() < dt * 6) this.ripple(f.joints[3].x, f.joints[3].y, "wake", 0.35);

      this.updateBody(f, dt);
    });
  }

  private updateBody(f: Fish, dt: number) {
    const seg = f.length / (JOINTS - 1), J = f.joints, maxBend = 0.13; // radians per joint: ~110° across the whole body at most
    J[0].x = f.x; J[0].y = f.y;
    let prevAng = f.heading + Math.PI; // direction pointing backward from the head
    for (let i = 1; i < JOINTS; i++) {
      let ang = Math.atan2(J[i].y - J[i - 1].y, J[i].x - J[i - 1].x);
      const bend = angleDiff(ang, prevAng);
      if (Math.abs(bend) > maxBend) ang = prevAng + Math.sign(bend) * maxBend;
      J[i].x = J[i - 1].x + Math.cos(ang) * seg; J[i].y = J[i - 1].y + Math.sin(ang) * seg;
      prevAng = ang;
    }
    // tail fin: springs toward where a straight continuation of the body would put it
    let ax = J[JOINTS - 1].x, ay = J[JOINTS - 1].y, dir = prevAng;
    for (let i = 0; i < TAIL; i++) {
      const rest = { x: ax + Math.cos(dir) * seg * 0.8, y: ay + Math.sin(dir) * seg * 0.8 }, p = f.tail[i], v = f.tailVel[i];
      v.x += (rest.x - p.x) * 140 * dt; v.y += (rest.y - p.y) * 140 * dt; v.x *= Math.exp(-dt * 14); v.y *= Math.exp(-dt * 14);
      p.x += v.x * dt; p.y += v.y * dt;
      const dx = p.x - ax, dy = p.y - ay, d = len(dx, dy) || 1; p.x = ax + dx / d * seg * 0.8; p.y = ay + dy / d * seg * 0.8;
      dir = Math.atan2(p.y - ay, p.x - ax); ax = p.x; ay = p.y;
    }
  }

  /** Spine with the muscle wave applied, for drawing. */
  pose(f: Fish): V[] {
    const out: V[] = [];
    for (let i = 0; i < JOINTS; i++) {
      const s = i / (JOINTS - 1), a = f.joints[Math.max(0, i - 1)], b = f.joints[Math.min(JOINTS - 1, i + 1)];
      let tx = a.x - b.x, ty = a.y - b.y; const tl = len(tx, ty) || 1; tx /= tl; ty /= tl;
      // amplitude: a little at the head, rising through the tail; strongest when working hard
      const amp = f.girth * (0.12 + 1.5 * s * s) * (0.15 + 0.85 * clamp(f.effort, 0, 1.2));
      const w = Math.sin(f.beat - s * 5.4) * amp;
      out.push({ x: f.joints[i].x - ty * w, y: f.joints[i].y + tx * w });
    }
    return out;
  }
}

// koipond — drawing the scene (fish, pads, food, shadows) into a 2D canvas.
// The water itself, ripples and the dither are done afterwards on the GPU (see gl.ts).
import type { Fish, Pond, V } from "./sim";

const TAU = Math.PI * 2;

/** Half-width of the body at s (0 nose → 1 tail root), as a fraction of girth. Round head, long taper. */
function profile(s: number) {
  if (s < 0.22) return 0.6 + 0.4 * Math.sin((s / 0.22) * Math.PI * 0.5);
  const k = (s - 0.22) / 0.78;
  return 0.08 + 0.92 * Math.pow(Math.cos(k * Math.PI * 0.5), 1.1);
}

type Frame = { p: V[]; tx: number[]; ty: number[]; L: V[]; R: V[] };

function frame(pond: Pond, f: Fish): Frame {
  const p = pond.pose(f), n = p.length, tx: number[] = [], ty: number[] = [], L: V[] = [], R: V[] = [];
  for (let i = 0; i < n; i++) {
    const a = p[Math.max(0, i - 1)], b = p[Math.min(n - 1, i + 1)];
    let x = a.x - b.x, y = a.y - b.y; const l = Math.hypot(x, y) || 1; x /= l; y /= l;
    tx.push(x); ty.push(y);
    const w = f.girth * profile(i / (n - 1));
    L.push({ x: p[i].x - y * w, y: p[i].y + x * w }); R.push({ x: p[i].x + y * w, y: p[i].y - x * w });
  }
  return { p, tx, ty, L, R };
}

function bodyPath(ctx: CanvasRenderingContext2D, g: Frame, f: Fish, ox = 0, oy = 0) {
  const { p, tx, ty, L, R } = g, n = p.length;
  ctx.beginPath();
  // rounded snout: an arc across the head
  const hw = f.girth * profile(0);
  const ang = Math.atan2(ty[0], tx[0]);
  ctx.arc(p[0].x + ox, p[0].y + oy, hw, ang - Math.PI / 2 - 0.0001, ang + Math.PI / 2 + 0.0001, true);
  for (let i = 0; i < n; i++) ctx.lineTo(R[i].x + ox, R[i].y + oy);
  for (let i = n - 1; i >= 0; i--) ctx.lineTo(L[i].x + ox, L[i].y + oy);
  ctx.closePath();
}

/** Point on the body at (u along, v across), using the posed spine. */
function onBody(g: Frame, f: Fish, u: number, v: number): { x: number; y: number; a: number; w: number } {
  const n = g.p.length, fi = u * (n - 1), i = Math.min(n - 2, Math.floor(fi)), k = fi - i;
  const x = g.p[i].x + (g.p[i + 1].x - g.p[i].x) * k, y = g.p[i].y + (g.p[i + 1].y - g.p[i].y) * k;
  const tx = g.tx[i], ty = g.ty[i], w = f.girth * profile(u);
  return { x: x - ty * w * v, y: y + tx * w * v, a: Math.atan2(ty, tx), w };
}

function tailFan(ctx: CanvasRenderingContext2D, g: Frame, f: Fish, ox = 0, oy = 0) {
  // a forked, flowing tail: two soft lobes that follow the trailing tail chain
  const n = g.p.length, root = g.p[n - 1], mid = f.tail[1], tip = f.tail[f.tail.length - 1];
  let dx = tip.x - root.x, dy = tip.y - root.y; const d = Math.hypot(dx, dy) || 1; dx /= d; dy /= d;
  const nx = -dy, ny = dx, spread = f.girth * 1.55, reach = f.girth * 1.25;
  const lobe = (side: number) => {
    const ex = tip.x + nx * spread * side + dx * reach, ey = tip.y + ny * spread * side + dy * reach;
    ctx.moveTo(root.x + nx * f.girth * 0.12 * side + ox, root.y + ny * f.girth * 0.12 * side + oy);
    ctx.bezierCurveTo(mid.x + nx * spread * 0.55 * side + ox, mid.y + ny * spread * 0.55 * side + oy, ex - dx * reach * 0.6 + ox, ey - dy * reach * 0.6 + oy, ex + ox, ey + oy);
    ctx.quadraticCurveTo(tip.x + dx * reach * 0.15 + nx * spread * 0.2 * side + ox, tip.y + dy * reach * 0.15 + ny * spread * 0.2 * side + oy, tip.x + ox, tip.y + oy);
    ctx.lineTo(root.x + ox, root.y + oy);
  };
  ctx.beginPath(); lobe(1); lobe(-1); ctx.closePath();
}

function fins(ctx: CanvasRenderingContext2D, g: Frame, f: Fish, ox = 0, oy = 0) {
  // pectoral fins sweep with a slow paddle; the fin on the inside of a turn tucks in
  const paddle = 0.5 + 0.5 * Math.sin(f.finPhase * 2.2);
  for (const side of [1, -1]) {
    const tuck = 1 - Math.max(0, side * f.turn) * 0.35;
    for (const [u, size] of [[0.24, 1.45], [0.58, 0.6]] as const) {
      const b = onBody(g, f, u, side);
      const back = b.a + Math.PI, out = b.a + side * Math.PI / 2;
      const reach = f.girth * (0.9 + paddle * 0.5) * size * tuck;
      // the fin points out and back from the body
      const ang = Math.atan2(Math.sin(out) * 0.6 + Math.sin(back) * 0.4, Math.cos(out) * 0.6 + Math.cos(back) * 0.4);
      const tx = b.x + Math.cos(ang) * reach, ty = b.y + Math.sin(ang) * reach;
      ctx.beginPath();
      ctx.moveTo(b.x + Math.cos(b.a) * f.girth * 0.35 * size + ox, b.y + Math.sin(b.a) * f.girth * 0.35 * size + oy);
      ctx.quadraticCurveTo(tx + Math.cos(b.a) * reach * 0.4 + ox, ty + Math.sin(b.a) * reach * 0.4 + oy, tx + ox, ty + oy);
      ctx.lineTo(b.x - Math.cos(b.a) * f.girth * 0.5 * size + ox, b.y - Math.sin(b.a) * f.girth * 0.5 * size + oy);
      ctx.closePath(); ctx.fill();
    }
  }
}

/** Darken a hex colour (for flanks) or lighten it (for the back). */
function shade(hexc: string, k: number) {
  const n = parseInt(hexc.slice(1), 16), r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const f = (c: number) => Math.round(k < 0 ? c * (1 + k) : c + (255 - c) * k);
  return `rgb(${f(r)},${f(g)},${f(b)})`;
}

/** Everything under the surface: shadows on the floor, then the fish (deepest first). */
export function drawUnder(ctx: CanvasRenderingContext2D, pond: Pond, shadow = 0.8, fish = true) {
  const W = ctx.canvas.width, H = ctx.canvas.height, sx = W / pond.w, sy = H / pond.h;
  ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.clearRect(0, 0, W, H); ctx.setTransform(sx, 0, 0, sy, 0, 0);
  const fishes = [...pond.fish].sort((a, b) => b.depth - a.depth);
  const frames = new Map(fishes.map((f) => [f, frame(pond, f)]));
  const unit = Math.min(pond.w, pond.h) * 0.11;

  // water plants on the floor: soft tapered blades, blurred by the water above them, swaying
  ctx.save();
  for (const w of pond.weeds) {
    const sway = Math.sin(pond.t * 0.6 + w.phase) * 0.3 + pond.current.x * 0.5, a = w.dir + sway, n = { x: -Math.sin(w.dir), y: Math.cos(w.dir) };
    const mx = w.x + Math.cos(w.dir + sway * 0.4) * w.len * 0.5, my = w.y + Math.sin(w.dir + sway * 0.4) * w.len * 0.5;
    const ex = w.x + Math.cos(a) * w.len, ey = w.y + Math.sin(a) * w.len, wd = w.len * 0.09;
    ctx.fillStyle = w.phase > 3 ? "rgba(52,82,46,0.5)" : "rgba(72,98,52,0.42)";
    ctx.beginPath(); ctx.moveTo(w.x + n.x * wd, w.y + n.y * wd);
    ctx.quadraticCurveTo(mx + n.x * wd * 1.4, my + n.y * wd * 1.4, ex, ey);
    ctx.quadraticCurveTo(mx - n.x * wd * 1.4, my - n.y * wd * 1.4, w.x - n.x * wd, w.y - n.y * wd);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();

  // shadows: fish near the surface throw softer shadows further away; pads shade the floor too
  ctx.save();
  if (fish) for (const f of fishes) {
    const g = frames.get(f)!, off = unit * (0.1 + (1 - f.depth) * 0.3);
    ctx.filter = `blur(${Math.max(0.8, unit * (0.025 + (1 - f.depth) * 0.04) * sx)}px)`;
    ctx.fillStyle = `rgba(0,20,25,${shadow * (0.6 + f.depth * 0.3)})`;
    bodyPath(ctx, g, f, off * 0.45, off); ctx.fill(); tailFan(ctx, g, f, off * 0.45, off); ctx.fill(); fins(ctx, g, f, off * 0.45, off);
  }
  ctx.filter = `blur(${Math.max(1, unit * 0.12 * sx)}px)`; ctx.fillStyle = `rgba(0,0,0,${shadow * 0.75})`;
  for (const p of pond.pads) { padPath(ctx, p.x + p.r * 0.35, p.y + p.r * 0.5, p.r, p.angle, p.notch); ctx.fill(); }
  if (pond.border > 0) for (const st of stonesFor(pond).stones) { const g = ctx.createRadialGradient(st.x + st.rx * 0.3, st.y + st.ry * 0.45, st.rx * 0.3, st.x + st.rx * 0.3, st.y + st.ry * 0.45, st.rx * 1.35); g.addColorStop(0, `rgba(0,0,0,${shadow * 0.6})`); g.addColorStop(1, "rgba(0,0,0,0)"); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(st.x + st.rx * 0.3, st.y + st.ry * 0.45, st.rx * 1.35, 0, TAU); ctx.fill(); }
  ctx.fillStyle = `rgba(0,0,0,${shadow * 0.5})`;
  for (const p of pond.petals) { const o = unit * (0.06 + p.z * 0.8); petalPath(ctx, p.x + o, p.y + o * 1.4, p.r * (1 + p.z * 0.6), p.angle); ctx.fill(); }
  ctx.restore();
  if (!fish) return;

  for (const f of fishes) {
    const g = frames.get(f)!, v = f.variety, fade = 1;
    // fins and tail: thin and translucent, with rays
    ctx.globalAlpha = 0.66; ctx.fillStyle = shade(v.fin, 0.3); tailFan(ctx, g, f); ctx.fill(); fins(ctx, g, f);
    ctx.save(); tailFan(ctx, g, f); ctx.clip();
    ctx.globalAlpha = fade * 0.25; ctx.strokeStyle = shade(v.fin, 0.4); ctx.lineWidth = Math.max(0.3, f.girth * 0.05);
    const root = g.p[g.p.length - 1];
    for (let k = -4; k <= 4; k++) { const tip = f.tail[f.tail.length - 1], dx = tip.x - root.x, dy = tip.y - root.y, l = Math.hypot(dx, dy) || 1; ctx.beginPath(); ctx.moveTo(root.x, root.y); ctx.lineTo(tip.x + (-dy / l) * f.girth * 0.3 * k + dx * 0.4, tip.y + (dx / l) * f.girth * 0.3 * k + dy * 0.4); ctx.stroke(); }
    ctx.restore();

    // body: base colour, then volume — darker flanks, a lit back
    ctx.globalAlpha = fade; ctx.fillStyle = v.base; bodyPath(ctx, g, f); ctx.fill();
    ctx.save(); bodyPath(ctx, g, f); ctx.clip();
    for (const s of f.spots) {
      const b = onBody(g, f, s.u, s.v);
      ctx.filter = `blur(${Math.max(0.3, f.girth * 0.05 * sx)}px)`; ctx.fillStyle = s.color;
      ctx.beginPath(); ctx.ellipse(b.x, b.y, f.length * s.ru, Math.max(0.5, b.w * s.rv), b.a, 0, TAU); ctx.fill();
    }
    ctx.filter = `blur(${Math.max(0.5, f.girth * 0.35 * sx)}px)`;
    ctx.strokeStyle = shade(v.base, -0.42); ctx.globalAlpha = fade * 0.5; ctx.lineWidth = f.girth * 0.75; bodyPath(ctx, g, f); ctx.stroke();
    ctx.strokeStyle = "#ffffff"; ctx.globalAlpha = fade * 0.3; ctx.lineWidth = f.girth * 0.55; ctx.lineCap = "round";
    ctx.beginPath(); const s0 = onBody(g, f, 0.08, 0); ctx.moveTo(s0.x, s0.y); for (const u of [0.2, 0.34, 0.48, 0.62]) { const b = onBody(g, f, u, 0); ctx.lineTo(b.x, b.y); } ctx.stroke();
    // scales: a faint net of small arcs over the body
    ctx.filter = "none"; ctx.globalAlpha = fade * 0.12; ctx.strokeStyle = shade(v.base, -0.5); ctx.lineWidth = Math.max(0.25, f.girth * 0.04);
    for (let u = 0.16; u < 0.86; u += 0.055) for (let vv = -0.7; vv <= 0.71; vv += 0.35) {
      const b = onBody(g, f, u + (Math.round(vv / 0.35) % 2 ? 0.027 : 0), vv), r = f.girth * 0.17;
      ctx.beginPath(); ctx.arc(b.x, b.y, r, b.a + Math.PI * 0.5, b.a + Math.PI * 1.5); ctx.stroke();
    }
    // deeper fish are seen through more water: a green-blue haze over the body
    ctx.globalAlpha = Math.min(0.45, f.depth * 0.45); ctx.fillStyle = "#123c3c"; ctx.fillRect(f.x - f.length * 2, f.y - f.length * 2, f.length * 4, f.length * 4);
    ctx.restore();
    // a small wet glint on the head and shoulders
    ctx.globalAlpha = fade * 0.5; ctx.fillStyle = "#ffffff"; ctx.filter = `blur(${Math.max(0.4, f.girth * 0.12 * sx)}px)`;
    { const b = onBody(g, f, 0.14, -0.25); ctx.beginPath(); ctx.ellipse(b.x, b.y, f.girth * 0.45, f.girth * 0.16, b.a, 0, TAU); ctx.fill(); }
    ctx.filter = "none";
    // eyes
    ctx.globalAlpha = fade * 0.9; ctx.fillStyle = "#0b0a0d";
    for (const side of [1, -1]) { const e = onBody(g, f, 0.07, side * 0.66); ctx.beginPath(); ctx.arc(e.x, e.y, Math.max(0.4, f.girth * 0.12), 0, TAU); ctx.fill(); }
  }
  ctx.globalAlpha = 1;
}

/** Things floating on the surface: food and lily pads. */
export function drawTop(ctx: CanvasRenderingContext2D, pond: Pond, props?: HTMLCanvasElement | true) {
  const W = ctx.canvas.width, H = ctx.canvas.height, sx = W / pond.w, sy = H / pond.h;
  ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.clearRect(0, 0, W, H); ctx.setTransform(sx, 0, 0, sy, 0, 0);
  const unit = Math.min(pond.w, pond.h) * 0.11;
  for (const p of pond.pellets) {
    const r = Math.max(0.8, unit * 0.04);
    const grd = ctx.createRadialGradient(p.x - r * 0.3, p.y - r * 0.3, r * 0.1, p.x, p.y, r);
    grd.addColorStop(0, "#f0d79a"); grd.addColorStop(1, "#9c7436");
    ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, TAU); ctx.fill();
  }
  for (const p of pond.petals) {
    // a sakura petal: pale pink, deeper at the base; larger and softer while still falling
    const r = p.r * (1 + p.z * 0.6), cx = Math.cos(p.angle), cy = Math.sin(p.angle);
    const grd = ctx.createLinearGradient(p.x - cx * r, p.y - cy * r, p.x + cx * r, p.y + cy * r);
    grd.addColorStop(0, scheme(pond).petal[0]); grd.addColorStop(1, scheme(pond).petal[1]);
    ctx.globalAlpha = p.z > 0 ? 0.92 : 1; ctx.fillStyle = grd; petalPath(ctx, p.x, p.y, r, p.angle); ctx.fill(); ctx.globalAlpha = 1;
  }
  // rain: faint streaks of falling drops
  if (pond.rain > 0) {
    ctx.strokeStyle = "rgba(235,245,240,0.22)"; ctx.lineWidth = Math.max(0.6, unit * 0.008);
    const n = Math.round(pond.rain * 40);
    ctx.beginPath();
    for (let i = 0; i < n; i++) { const x = Math.random() * pond.w, y = Math.random() * pond.h, l = unit * (0.08 + Math.random() * 0.12); ctx.moveTo(x, y); ctx.lineTo(x + l * 0.25, y + l); }
    ctx.stroke();
  }
  // splash droplets and wake sparks: small points of light, fading
  for (const sp of pond.sparks) {
    if (sp.age < 0) continue; const k = sp.age / sp.life, arc = sp.drip ? Math.sin(k * Math.PI) : 1 - k;
    ctx.fillStyle = `rgba(240,250,248,${(sp.drip ? 0.75 : 0.6) * (sp.drip ? 0.4 + 0.6 * arc : arc)})`;
    ctx.beginPath(); ctx.arc(sp.x, sp.y - (sp.drip ? arc * unit * 0.08 : 0), sp.r * (sp.drip ? 0.7 + arc * 0.7 : 0.6 + arc * 0.5), 0, TAU); ctx.fill();
  }
  for (const fl of pond.flashes) { const k = 1 - fl.age / 0.3, R = unit * (0.12 + fl.age * 0.6); const g = ctx.createRadialGradient(fl.x, fl.y, 0, fl.x, fl.y, R); g.addColorStop(0, `rgba(255,255,255,${0.3 * k})`); g.addColorStop(1, "rgba(255,255,255,0)"); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(fl.x, fl.y, R, 0, TAU); ctx.fill(); }
  for (const b of pond.bubbles) {
    if (b.age < 0) continue;
    const k = Math.min(1, b.age / 0.3), r = b.r * (0.6 + 0.4 * k);
    ctx.strokeStyle = `rgba(235,250,248,${0.55 * k})`; ctx.lineWidth = Math.max(0.6, r * 0.18);
    ctx.beginPath(); ctx.arc(b.x, b.y, r, 0, TAU); ctx.stroke();
    ctx.fillStyle = `rgba(255,255,255,${0.7 * k})`; ctx.beginPath(); ctx.arc(b.x - r * 0.35, b.y - r * 0.35, r * 0.25, 0, TAU); ctx.fill();
  }
  if (props) {
    // lit 3D pads and rocks, then the flowers on top of their pads
    if (props !== true) { ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.drawImage(props, 0, 0, W, H); ctx.restore(); }
    for (const p of pond.pads) if (p.flower) drawLily(ctx, p.x + Math.cos(p.angle + Math.PI) * p.r * 0.15, p.y + Math.sin(p.angle + Math.PI) * p.r * 0.15, p.r * 0.48, p.angle * 3, scheme(pond));
  } else {
    for (const p of pond.pads) drawPad(ctx, p, scheme(pond));
    if (pond.border > 0) drawBorder(ctx, pond, scheme(pond));
  }
}

// colours for floating things and the border, per art style, so they sit in the same world as the water
type Scheme = { pads: string[][]; vein: string; petal: [string, string]; lily: [string, string]; heart: [string, string]; stone: string[]; stoneDark: string; moss: string };
const SCHEMES: Record<string, Scheme> = {
  // woodblock print: sage/olive greens, pale sakura, cream lilies, slate and cream stones
  ink: { pads: [["#7f8d5c", "#66744a", "#4c5838"], ["#98a06a", "#7f8955", "#606a3f"], ["#6c7a55", "#566444", "#3f4a32"]], vein: "rgba(232,226,200,0.5)", petal: ["#e3aab3", "#f6e2e2"], lily: ["#efe8d6", "#fbf7ee"], heart: ["#e9b648", "#cf8f2c"], stone: ["#8e958f", "#a3a79c", "#767e7c", "#b6b3a4"], stoneDark: "#3a4250", moss: "#5f6d45" },
  // soft garden photo: dusty olive, khaki and rose pads (from the reference), muted sakura
  garden: { pads: [["#8c8f52", "#6b6e36", "#4b4d22"], ["#b3aa6b", "#9a9250", "#746c34"], ["#a88466", "#8c6a4e", "#654a36"]], vein: "rgba(235,228,190,0.5)", petal: ["#d9a4ad", "#f1dcdc"], lily: ["#f0e9da", "#fffaf0"], heart: ["#f0c45a", "#d99a2a"], stone: ["#8d8c80", "#a4a094", "#77786e", "#b5b0a0"], stoneDark: "#3e4038", moss: "#6b7246" },
  // deep stone pond: cool greens, pale petals
  natural: { pads: [["#4f7a52", "#3a6040", "#284430"], ["#6a8a56", "#527044", "#3a5232"], ["#5a6e4a", "#46583a", "#33402b"]], vein: "rgba(205,225,190,0.45)", petal: ["#dba6b2", "#f5e4e8"], lily: ["#eee9df", "#fbf9f4"], heart: ["#f0c45a", "#d99a2a"], stone: ["#6f7672", "#858a83", "#5d6462", "#9a9a90"], stoneDark: "#26302e", moss: "#4c6a44" },
};
const scheme = (p: Pond) => SCHEMES[p.style] ?? SCHEMES.natural;

function drawPad(ctx: CanvasRenderingContext2D, p: Pond["pads"][number], sc: Scheme) {
  const tone = sc.pads[p.tone < 0.45 ? 0 : p.tone < 0.75 ? 1 : 2];
  // leaf body: lit toward the upper left, darker at the edge
  const grd = ctx.createRadialGradient(p.x - p.r * 0.25, p.y - p.r * 0.3, p.r * 0.05, p.x, p.y, p.r * 1.02);
  grd.addColorStop(0, tone[0]); grd.addColorStop(0.7, tone[1]); grd.addColorStop(1, tone[2]);
  ctx.fillStyle = grd; padPath(ctx, p.x, p.y, p.r, p.angle, p.notch); ctx.fill();
  ctx.save(); padPath(ctx, p.x, p.y, p.r, p.angle, p.notch); ctx.clip();
  // veins: from the centre, gently curving, fading toward the rim
  const n = 18;
  for (let i = 0; i <= n; i++) {
    const a = p.angle + p.notch * 0.5 + (i / n) * (TAU - p.notch), bend = 0.12 * Math.sin(i * 1.7);
    const g2 = ctx.createLinearGradient(p.x, p.y, p.x + Math.cos(a) * p.r, p.y + Math.sin(a) * p.r);
    g2.addColorStop(0, sc.vein); g2.addColorStop(1, "rgba(0,0,0,0)");
    ctx.strokeStyle = g2; ctx.lineWidth = Math.max(0.4, p.r * 0.018);
    ctx.beginPath(); ctx.moveTo(p.x, p.y);
    ctx.quadraticCurveTo(p.x + Math.cos(a + bend) * p.r * 0.5, p.y + Math.sin(a + bend) * p.r * 0.5, p.x + Math.cos(a) * p.r * 0.97, p.y + Math.sin(a) * p.r * 0.97); ctx.stroke();
  }
  // rim: a slightly raised, lighter edge
  ctx.strokeStyle = "rgba(60,55,25,0.35)"; ctx.lineWidth = Math.max(0.6, p.r * 0.04); padPath(ctx, p.x, p.y, p.r * 0.985, p.angle, p.notch); ctx.stroke();
  ctx.fillStyle = "rgba(255,255,255,0.06)"; ctx.beginPath(); ctx.ellipse(p.x - p.r * 0.32, p.y - p.r * 0.36, p.r * 0.4, p.r * 0.2, -0.6, 0, TAU); ctx.fill();
  ctx.restore();
  if (p.flower) drawLily(ctx, p.x + Math.cos(p.angle + Math.PI) * p.r * 0.15, p.y + Math.sin(p.angle + Math.PI) * p.r * 0.15, p.r * 0.48, p.angle * 3, sc);
}

/** A white water lily seen from above: two rings of pointed petals around a golden centre. */
function drawLily(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, rot: number, sc: Scheme) {
  ctx.save();

  for (const [ring, count, len, wid, off] of [[0, 10, 1, 0.3, 0], [1, 9, 0.78, 0.26, 0.5]] as const) {
    for (let i = 0; i < count; i++) {
      const a = rot + ((i + off) / count) * TAU, L = r * len, W = r * wid;
      const tx = x + Math.cos(a) * L, ty = y + Math.sin(a) * L, nx = -Math.sin(a) * W, ny = Math.cos(a) * W;
      const g = ctx.createLinearGradient(x, y, tx, ty);
      g.addColorStop(0, sc.lily[0]); g.addColorStop(1, sc.lily[1]);
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.moveTo(x, y);
      ctx.quadraticCurveTo(x + Math.cos(a) * L * 0.5 + nx, y + Math.sin(a) * L * 0.5 + ny, tx, ty);
      ctx.quadraticCurveTo(x + Math.cos(a) * L * 0.5 - nx, y + Math.sin(a) * L * 0.5 - ny, x, y);
      ctx.fill();
      if (ring === 0 && i === 0) { ctx.shadowColor = "transparent"; }
    }
  }
  ctx.shadowColor = "transparent";
  // golden centre with stamens
  const c = ctx.createRadialGradient(x - r * 0.05, y - r * 0.05, 0, x, y, r * 0.28);
  c.addColorStop(0, sc.heart[0]); c.addColorStop(1, sc.heart[1]);
  ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, y, r * 0.26, 0, TAU); ctx.fill();
  ctx.fillStyle = "#fff0a0";
  for (let i = 0; i < 16; i++) { const a = rot + (i / 16) * TAU; ctx.beginPath(); ctx.arc(x + Math.cos(a) * r * 0.2, y + Math.sin(a) * r * 0.2, r * 0.03, 0, TAU); ctx.fill(); }
  ctx.restore();
}

/** Single-canvas drawing (used by the simple, stylised water). */
export function drawScene(ctx: CanvasRenderingContext2D, pond: Pond, shadow = 0.5) {
  drawUnder(ctx, pond, shadow);
  const top = document.createElement("canvas"); top.width = ctx.canvas.width; top.height = ctx.canvas.height;
  drawTop(top.getContext("2d")!, pond);
  ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.drawImage(top, 0, 0);
}

// a border of rounded stones around the pond: bigger and piled up in the corners, a dark wet edge
// at the water line and their shadow falling onto the water. Stones are seeded, so they never move.
type Stone = { x: number; y: number; rx: number; ry: number; a: number; c: number; moss: boolean; wob: number[] };
let stoneCache: { key: string; stones: Stone[]; shoreline: [number, number][] } | null = null;
export function stonesFor(pond: Pond) {
  const key = `${Math.round(pond.w)}x${Math.round(pond.h)}:${pond.border.toFixed(1)}`;
  if (stoneCache?.key === key) return stoneCache;
  let seed = 4242; const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
  const B = pond.border, stones: Stone[] = [];
  const make = (x: number, y: number, s: number) => stones.push({ x, y, rx: s * (0.8 + rnd() * 0.45), ry: s * (0.6 + rnd() * 0.3), a: rnd() * Math.PI, c: Math.floor(rnd() * 4), moss: rnd() < 0.35, wob: Array.from({ length: 12 }, () => 0.92 + rnd() * 0.12) });
  // one natural cluster in the lower-left corner: two big rocks, a few smaller ones tumbling out
  make(B * 1.2, pond.h - B * 1.0, B * 1.9); make(B * 3.0, pond.h - B * 0.6, B * 1.3); make(B * 0.6, pond.h - B * 2.9, B * 1.2);
  for (let k = 0; k < 7; k++) { const a = rnd() * Math.PI * 0.5, d = B * (2.4 + rnd() * 1.6); make(Math.cos(a) * d, pond.h - Math.sin(a) * d, B * (0.35 + rnd() * 0.4)); }
  stones.sort((p, q) => q.rx - p.rx);
  stoneCache = { key, stones, shoreline: [] };
  return stoneCache;
}

function stonePath(ctx: CanvasRenderingContext2D, s: Stone, dx = 0, dy = 0, grow = 1) {
  const n = s.wob.length; ctx.beginPath();
  for (let i = 0; i <= n + 1; i++) {
    const k = i % n, a = (k / n) * Math.PI * 2, r = s.wob[k] * grow;
    const px = s.x + dx + Math.cos(s.a) * Math.cos(a) * s.rx * r - Math.sin(s.a) * Math.sin(a) * s.ry * r;
    const py = s.y + dy + Math.sin(s.a) * Math.cos(a) * s.rx * r + Math.cos(s.a) * Math.sin(a) * s.ry * r;
    if (i === 0) ctx.moveTo(px, py); else { const pk = (k + n - 1) % n, pa = (pk / n) * Math.PI * 2; const mx = (px + s.x + dx + Math.cos(s.a) * Math.cos(pa) * s.rx * s.wob[pk] * grow - Math.sin(s.a) * Math.sin(pa) * s.ry * s.wob[pk] * grow) / 2; const my = (py + s.y + dy + Math.sin(s.a) * Math.cos(pa) * s.rx * s.wob[pk] * grow + Math.cos(s.a) * Math.sin(pa) * s.ry * s.wob[pk] * grow) / 2; ctx.quadraticCurveTo(mx, my, (mx + px) / 2, (my + py) / 2); }
  }
  ctx.closePath();
}

let borderLayer: { key: string; canvas: HTMLCanvasElement } | null = null;
function drawBorder(ctx: CanvasRenderingContext2D, pond: Pond, sc: Scheme) {
  // drawn once into its own canvas (it never moves), then stamped each frame
  const W = ctx.canvas.width, H = ctx.canvas.height, key = `${W}x${H}:${pond.style}:${pond.border.toFixed(1)}`;
  if (borderLayer?.key !== key) {
    const c = document.createElement("canvas"); c.width = W; c.height = H;
    const g = c.getContext("2d")!; g.setTransform(W / pond.w, 0, 0, H / pond.h, 0, 0);
    const { stones } = stonesFor(pond), B = pond.border;
    g.save(); g.fillStyle = "rgba(0,0,0,0.3)"; g.filter = `blur(${B * 0.3 * (W / pond.w)}px)`;
    for (const s of stones) { stonePath(g, s, B * 0.15, B * 0.28, 1.06); g.fill(); }
    g.restore();
    for (const s of stones) {
      const grd = g.createRadialGradient(s.x - s.rx * 0.35, s.y - s.ry * 0.4, s.rx * 0.1, s.x, s.y, s.rx * 1.15);
      grd.addColorStop(0, sc.stone[s.c]); grd.addColorStop(0.7, sc.stone[(s.c + 2) % 4]); grd.addColorStop(1, sc.stoneDark);
      g.fillStyle = grd; stonePath(g, s); g.fill();
      if (s.moss) { g.save(); stonePath(g, s); g.clip(); g.fillStyle = sc.moss; g.globalAlpha = 0.6; g.beginPath(); g.ellipse(s.x - s.rx * 0.3, s.y - s.ry * 0.45, s.rx * 0.6, s.ry * 0.4, s.a, 0, Math.PI * 2); g.fill(); g.restore(); }
    }
    borderLayer = { key, canvas: c };
  }
  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.drawImage(borderLayer.canvas, 0, 0); ctx.restore();
}

function petalPath(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, a: number) {
  const c = Math.cos(a), s = Math.sin(a), P = (u: number, v: number) => [x + c * u - s * v, y + s * u + c * v] as const;
  ctx.beginPath();
  ctx.moveTo(...P(-r, 0));
  ctx.bezierCurveTo(...P(-r * 0.4, -r * 0.75), ...P(r * 0.7, -r * 0.7), ...P(r, -r * 0.12));
  ctx.lineTo(...P(r * 0.82, 0));
  ctx.lineTo(...P(r, r * 0.12));
  ctx.bezierCurveTo(...P(r * 0.7, r * 0.7), ...P(-r * 0.4, r * 0.75), ...P(-r, 0));
  ctx.closePath();
}

function padPath(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, angle: number, notch: number) {
  ctx.beginPath(); ctx.moveTo(x, y); ctx.arc(x, y, r, angle + notch * 0.5, angle + TAU - notch * 0.5); ctx.closePath();
}

// koipond — the whole pond on ONE three.js renderer, so nothing is copied between GPU contexts.
//   1. ripple simulation: two half-float render targets, ping-ponged
//   2. koi: three.js meshes rendered into a render target
//   3. lily pads and rocks: three.js meshes rendered into a render target
//   4. the 2D layers (floor shadows; petals, flowers, sparks) are uploaded as canvas textures
//   5. one full-screen pass composites water, floor, koi, light and floaters onto the screen
import * as THREE from "three";
import { COMPOSE, STRENGTH, WAVE, hex, type WaterLook } from "./water";
import type { Pond, Ripple } from "./sim";

const VERT = `in vec3 position; out vec2 uv; void main(){ uv = position.xy * .5 + .5; gl_Position = vec4(position.xy, 0., 1.); }`;
const strip = (src: string) => src.replace(/^#version 300 es\s*/, "");

export function createStage(canvas: HTMLCanvasElement) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, alpha: false, powerPreference: "high-performance", preserveDrawingBuffer: true });
  renderer.setPixelRatio(1);
  renderer.autoClear = false;
  const quadCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const quadGeo = new THREE.PlaneGeometry(2, 2);

  // 1. ripples
  const rtOpts = { type: THREE.HalfFloatType, format: THREE.RGBAFormat, minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter, depthBuffer: false, wrapS: THREE.ClampToEdgeWrapping, wrapT: THREE.ClampToEdgeWrapping } as const;
  let WW = 0, WH = 0, cur = 0;
  let states = [new THREE.WebGLRenderTarget(1, 1, rtOpts), new THREE.WebGLRenderTarget(1, 1, rtOpts)];
  const drops = Array.from({ length: 16 }, () => new THREE.Vector4());
  const waveMat = new THREE.RawShaderMaterial({
    glslVersion: THREE.GLSL3, vertexShader: VERT, fragmentShader: strip(WAVE), depthTest: false, depthWrite: false,
    uniforms: { state: { value: null }, texel: { value: new THREE.Vector2() }, drops: { value: drops }, dropN: { value: 0 } },
  });
  const waveScene = new THREE.Scene(); waveScene.add(new THREE.Mesh(quadGeo, waveMat));
  const sizeWaves = (aspect: number) => {
    const w = 384, h = Math.max(32, Math.round(384 / aspect));
    if (w === WW && h === WH) return;
    WW = w; WH = h;
    states.forEach((s) => s.dispose());
    states = [new THREE.WebGLRenderTarget(w, h, rtOpts), new THREE.WebGLRenderTarget(w, h, rtOpts)];
    for (const s of states) { renderer.setRenderTarget(s); renderer.setClearColor(0x000000, 1); renderer.clear(); }
    renderer.setRenderTarget(null);
  };

  // 4. 2D layers as textures (uploaded each frame; no read-back)
  const mkCanvasTex = () => { const t = new THREE.Texture(); t.minFilter = THREE.LinearFilter; t.magFilter = THREE.LinearFilter; t.generateMipmaps = false; t.colorSpace = THREE.NoColorSpace; return t; };
  const underTex = mkCanvasTex(), topTex = mkCanvasTex();

  // 5. composite
  const composeMat = new THREE.RawShaderMaterial({
    glslVersion: THREE.GLSL3, vertexShader: VERT, fragmentShader: strip(COMPOSE), depthTest: false, depthWrite: false,
    uniforms: {
      waves: { value: null }, fish: { value: underTex }, top: { value: topTex }, fishgl: { value: null }, props: { value: null },
      bakeMode: { value: 0 }, useBake: { value: 0 }, floorTex: { value: null },
      useGL: { value: 1 }, fishPremul: { value: 1 }, fishLinear: { value: 1 }, useProps: { value: 0 }, flipT: { value: 1 },
      res: { value: new THREE.Vector2() }, pond: { value: new THREE.Vector2() }, wtexel: { value: new THREE.Vector2() },
      t: { value: 0 }, px: { value: 1 }, mode: { value: 1 }, bright: { value: 1 }, sand: { value: 0 }, causticAmt: { value: 1 }, clarity: { value: 1 }, waveAmt: { value: 1 }, film: { value: 0 },
      absorbK: { value: new THREE.Vector3(2.4, 0.92, 0.78) }, waterDeep: { value: new THREE.Vector3() }, waterShallow: { value: new THREE.Vector3() }, tint: { value: new THREE.Vector3(1, 1, 1) },
      c0: { value: new THREE.Vector3() }, c1: { value: new THREE.Vector3() }, c2: { value: new THREE.Vector3() }, c3: { value: new THREE.Vector3() },
    },
  });
  const composeScene = new THREE.Scene(); composeScene.add(new THREE.Mesh(quadGeo, composeMat));
  const injected = new WeakSet<Ripple>();
  // style changes: the new look spreads out from a point as a widening ripple; both looks render meanwhile
  const blendMat = new THREE.RawShaderMaterial({
    glslVersion: THREE.GLSL3, vertexShader: VERT, depthTest: false, depthWrite: false,
    uniforms: { fromTex: { value: null }, toTex: { value: null }, origin: { value: new THREE.Vector2(0.5, 0.5) }, radius: { value: 0 }, aspect: { value: 1 } },
    fragmentShader: `precision highp float; in vec2 uv; out vec4 o;
      uniform sampler2D fromTex, toTex; uniform vec2 origin; uniform float radius, aspect;
      void main(){
        vec2 d = (uv - origin) * vec2(aspect, 1.); float r = length(d);
        float edge = r - radius;
        // a soft, wobbling wavefront: the old look bends a little just ahead of it
        vec2 bend = normalize(d + 1e-5) * exp(-edge * edge * 900.) * .012;
        vec4 a = texture(fromTex, uv + bend / vec2(aspect, 1.)), b = texture(toTex, uv);
        float k = smoothstep(.012, -.012, edge);
        vec4 c = mix(a, b, k);
        c.rgb += exp(-edge * edge * 2500.) * .18;   // light caught on the wavefront
        o = vec4(c.rgb, 1.);
      }`,
  });
  const blendScene = new THREE.Scene(); blendScene.add(new THREE.Mesh(quadGeo, blendMat));
  let rtFrom: THREE.WebGLRenderTarget | null = null, rtTo: THREE.WebGLRenderTarget | null = null;
  let shown: WaterLook | null = null, shownKey = "", trans: { from: WaterLook; t0: number; origin: [number, number] } | null = null;
  const lookKey = (l: WaterLook) => JSON.stringify([l.mode, l.deep, l.shallow, l.floor, l.palette, l.film, l.pixel]);
  // the floor is static: bake it (lit) into a texture whenever the look or pond size changes
  let floorRT: THREE.WebGLRenderTarget | null = null, floorKey = "";
  const v3 = (u: THREE.Vector3, h: string) => { const [r, g, b] = hex(h); u.set(r, g, b); };

  return {
    renderer,
    setSize(w: number, h: number) { renderer.setSize(w, h, false); },
    render(o: { under: HTMLCanvasElement; top: HTMLCanvasElement; pond: Pond; look: WaterLook; dpr: number; fish: THREE.Texture | null; props: THREE.Texture | null; origin?: [number, number] }) {
      const { pond } = o; let look = o.look;
      const nk = lookKey(o.look);
      if (shown && nk !== shownKey && !trans) trans = { from: shown, t0: pond.t, origin: o.origin ?? [0.5, 0.5] };
      if (nk !== shownKey) { shown = o.look; shownKey = nk; }
      sizeWaves(pond.w / pond.h);
      // new disturbances become drops in the height field
      let n = 0; const short = Math.min(pond.w, pond.h);
      for (const r of pond.ripples) {
        if (injected.has(r) || r.age < 0 || n >= 16) continue;
        injected.add(r);
        const [rad, str] = STRENGTH[r.kind];
        drops[n++].set(r.x / pond.w, r.y / pond.h, (rad * short) / pond.w, str * r.power * 0.05);
      }
      waveMat.uniforms.texel.value.set(1 / WW, 1 / WH);
      for (let i = 0; i < 2; i++) {
        waveMat.uniforms.state.value = states[cur].texture; waveMat.uniforms.dropN.value = i === 0 ? n : 0;
        renderer.setRenderTarget(states[1 - cur]); renderer.render(waveScene, quadCam); cur = 1 - cur;
      }
      renderer.setRenderTarget(null);
      // layers
      underTex.image = o.under; underTex.needsUpdate = true;
      topTex.image = o.top; topTex.needsUpdate = true;
      const U = composeMat.uniforms, size = renderer.getDrawingBufferSize(new THREE.Vector2());
      const setLook = (lk: WaterLook) => { look = lk;
      U.waves.value = states[cur].texture; U.fishgl.value = o.fish; U.useGL.value = o.fish ? 1 : 0;
      U.props.value = o.props; U.useProps.value = o.props ? 1 : 0;
      U.res.value.copy(size); U.pond.value.set(pond.w, pond.h); U.wtexel.value.set(1 / WW, 1 / WH);
      U.t.value = pond.t; U.px.value = Math.max(1, look.pixel * o.dpr);
      U.mode.value = look.mode === "dither" ? 0 : look.mode === "ink" ? 2 : 1; U.bright.value = look.bright ?? 1;
      U.sand.value = look.floor === "pebbles" ? 2 : look.floor === "sand" ? 1 : 0; U.causticAmt.value = look.caustics ?? 1;
      U.clarity.value = look.clarity ?? 1; U.film.value = look.film ? 1 : 0; U.waveAmt.value = look.waves ?? 1;
      const ab = look.absorb ?? [2.4, 0.92, 0.78]; U.absorbK.value.set(ab[0], ab[1], ab[2]);
      v3(U.waterDeep.value, look.deep); v3(U.waterShallow.value, look.shallow); v3(U.tint.value, look.tint ?? "#ffffff");
      look.palette.forEach((c, i) => v3(U[`c${i}`].value, c)); };
      setLook(o.look);
      const fk = `${look.floor}|${pond.w.toFixed(0)}x${pond.h.toFixed(0)}`;
      if (fk !== floorKey) {
