  col *= 1. - .35 * pow(length((st - .5) * vec2(1.1, 1.)), 2.2);
  col *= bright;


  // ---------------------------------------------------------------- INK: a woodblock-print pond
  if (mode > 1.5){
    vec3 INK = vec3(.11, .12, .2), DEEP = vec3(.16, .22, .33), MID = vec3(.27, .38, .44), SAGE = vec3(.5, .6, .55), CREAM = vec3(.93, .89, .8);
    // bokashi: deep indigo in the middle of the pond, lighter toward the banks, in a few soft steps
    float bank = smoothstep(.1, .9, length((st - .5) * vec2(1.25, 1.)));
    float stepB = floor((bank + fbm(st * 3. + 2.) * .25) * 4.) / 4.;
    vec3 wc = mix(DEEP, mix(MID, SAGE, .55), stepB);
    // the floor shows as faint printed stones
    float fhI; floorColour(q, fhI);
    wc = mix(wc, wc * 1.08, step(.45, fhI));
    // light on the floor as cream print lines; ripples as printed rings
    float web2 = lagoonCaustic(q * .9, n.xy).g;
    wc = mix(wc, mix(wc, CREAM, .32), smoothstep(.62, .82, web2) * (1. - bank * .4));
    vec2 gw = vec2(hr - hl, hu - hd) * 70.;
    float ring = smoothstep(.35, .55, length(gw)) * (1. - smoothstep(.55, 1.1, length(gw)) * .5);
    wc = mix(wc, CREAM, ring * .75);
    // shadows of koi and pads: flat indigo
    vec4 sh = T(fish, clamp(st, vec2(.001), vec2(.999)));
    wc = mix(wc, INK, max(shadowA * .55, (1. - step(.12, dot(sh.rgb, vec3(.33)))) * sh.a * .45));
    // koi: their colours in three flat tone bands, with an ink outline
    vec2 px2 = 1.6 / res;
    vec4 fk = T(fishgl, clamp(st + refrFish, vec2(.001), vec2(.999)));
    vec3 fc = fishPremul > .5 ? fk.rgb / max(fk.a, .001) : fk.rgb;
    if (fishLinear > .5) fc = srgb(fc);
    float fl0 = dot(fc, vec3(.299, .587, .114));
    // snap to the print palette (cream, vermilion, orange, gold, ink), then shade in two flat bands
    vec3 P[5] = vec3[5](CREAM, vec3(.84, .25, .12), vec3(.92, .47, .16), vec3(.9, .66, .24), INK);
    float best = 9.; vec3 fq = CREAM;
    vec3 fn2 = fc / max(fl0, .05) * .6;
    for (int k = 0; k < 5; k++){ float d = distance(fn2, P[k] / max(dot(P[k], vec3(.299, .587, .114)), .05) * .6) + abs(fl0 - dot(P[k], vec3(.299, .587, .114))) * .8; if (d < best){ best = d; fq = P[k]; } }
    fq *= fl0 < dot(fq, vec3(.299, .587, .114)) * .72 ? .8 : 1.;
    float aN = 0., aX = 1.;
    for (int k = 0; k < 4; k++){ vec2 o = vec2(k == 0 ? 1. : k == 1 ? -1. : 0., k == 2 ? 1. : k == 3 ? -1. : 0.) * px2; float a2 = T(fishgl, clamp(st + refrFish + o, vec2(.001), vec2(.999))).a; aN = max(aN, a2); aX = min(aX, a2); }
    // fins are thinner than the body (part alpha): a pale membrane, then the solid body on top
    float finM = smoothstep(.12, .3, fk.a) * (1. - step(.75, fk.a));
    vec3 ic = mix(wc, mix(wc, CREAM, .62), finM);
    ic = mix(ic, fq, step(.75, fk.a));
    ic = mix(ic, INK, smoothstep(.3, .6, aN - aX));
    // floating things: pads and petals posterised, outlined
    float tN = 0., tX = 1.;
    for (int k = 0; k < 4; k++){ vec2 o = vec2(k == 0 ? 1. : k == 1 ? -1. : 0., k == 2 ? 1. : k == 3 ? -1. : 0.) * px2; float a2 = T(top, st + o).a; tN = max(tN, a2); tX = min(tX, a2); }
    vec3 tc = tp.rgb; float tl = dot(tc, vec3(.299, .587, .114));
    tc = tc * (tl < .3 ? .8 : tl < .6 ? 1. : 1.08);
    ic = mix(ic, tc, step(.5, tp.a));
    ic = mix(ic, INK, smoothstep(.3, .6, tN - tX));
    // paper: fine grain and fibres
    float grain = vnoise(gl_FragCoord.xy * .9) * .5 + vnoise(gl_FragCoord.xy * .15 + 7.) * .5;
    ic *= .92 + .09 * grain;
    ic = mix(ic, ic * vec3(1.02, 1., .95), .5);
    o = vec4(ic, 1);
    return;
  }
  if (mode < .5){
    col = mix(srgb(col), tp.rgb, tp.a);
    float l = pow(clamp(dot(col, vec3(.299, .587, .114)) * 1.05, 0., 1.), 1.1);
    // the water sits low (dark, quiet); the koi are lifted into the light tones so they read clearly,
    // whites to the brightest colour, red and orange patches one step down, sumi stays dark
    float fl0 = dot(srgb(frgb), vec3(.299, .587, .114));
    float koiL = fl0 > .62 ? .98 : fl0 > .3 ? .7 : .22;
    // the water's movement gets its own tones so the dither can't swallow it:
    // ripples and wakes snap to the bright tone, the light web and wind sheen lift the water a step
    float waterL = l * .6 + cau.g * .08 * min(causticAmt, 1.5) + smoothstep(.05, .5, length(n.xy)) * .1;
    waterL = max(waterL, smoothstep(.05, .38, ripL) * .95);
    // fins and tails are thinner (part alpha): a pale membrane tone; the solid body gets its own colours
    float finM = smoothstep(.1, .3, isFish) * (1. - smoothstep(.86, .97, isFish));
    float bodyM = smoothstep(.86, .97, isFish);
    l = mix(waterL, .58, finM * (1. - tp.a));
    l = mix(l, koiL, bodyM * (1. - tp.a));
    float k = clamp(l * 3. + bayer(gl_FragCoord.xy / px) - .5, 0., 3.);
    o = vec4(k < 1. ? mix(c0, c1, step(.5, k)) : k < 2. ? mix(c1, c2, step(1.5, k)) : mix(c2, c3, step(2.5, k)), 1);
  } else {
    // filmic tone curve (ACES fit) and a whisper of grain
    col *= 1.5;
    col = srgb(clamp((col * (2.51 * col + .03)) / (col * (2.43 * col + .59) + .14), 0., 1.));
    if (film > .5) {
      // the reference's look: a little desaturated, warm, faded blacks, soft highlights
      float l = dot(col, vec3(.299, .587, .114));
      col = mix(vec3(l), col, mix(.8, 1.15, isFish));
      col = (col - .45) * 1.12 + .45;
      col = col * vec3(.9, .91, .84) + vec3(.045, .05, .03);
    }
    // things floating on top (lily pads, food) are not under water: drawn after the tone curve
    col = mix(col, tp.rgb * (1. - .35 * pow(length((st - .5) * vec2(1.1, 1.)), 2.2)), tp.a);
    col += (h21(gl_FragCoord.xy + fract(t) * 91.) - .5) * .018;
    o = vec4(col, 1);
  }
}`;

export const hex = (h: string) => { const n = parseInt(h.replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; };

export interface WaterLook { mode: "dither" | "color" | "ink"; palette: [string, string, string, string]; deep: string; shallow: string; tint?: string; pixel: number; bright?: number; floor?: "sand" | "stones" | "pebbles"; caustics?: number; clarity?: number; waves?: number; film?: boolean; absorb?: [number, number, number] }

export const STRENGTH: Record<Ripple["kind"], [number, number]> = { tap: [0.034, 2.6], drop: [0.012, 0.7], nibble: [0.01, 0.5], wake: [0.012, 0.45] }; // radius (of short side), strength

// koipond — the water pass on the GPU. Takes the drawn scene as a texture and adds:
// the water (depth, drifting light, caustics), ripples that bend everything under them and catch the
// light, and finally the look: an ordered dither to a 4-colour palette, or natural colour with grain.
import type { Ripple } from "./sim";

const MAX_RIPPLES = 24;

const VERT = `attribute vec2 p;varying vec2 uv;void main(){uv=p*.5+.5;gl_Position=vec4(p,0,1);}`;

const FRAG = `precision highp float;
varying vec2 uv;
uniform sampler2D scene;
uniform vec2 res, pond;
uniform float t, px, mode;
uniform vec3 deep, shallow, c0, c1, c2, c3;
uniform vec4 rip[${MAX_RIPPLES}];
uniform vec2 ripKind[${MAX_RIPPLES}];
uniform int ripN;

float hash(vec2 p){return fract(sin(dot(p,vec2(41.3,289.1)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+1.),f.x),f.y);}
// light through a moving surface: two warped sine lattices, sharpened where they cross
float caustic(vec2 q){
  vec2 w=q+vec2(noise(q*.7+t*.05),noise(q*.7-t*.04))*1.6;
  float a=abs(sin(w.x*2.1+t*.35)+sin(w.y*1.7-t*.28)+sin((w.x+w.y)*1.3+t*.2));
  return pow(clamp(1.-a*.42,0.,1.),6.);
}
// 8x8 ordered dither threshold
float bayer2(vec2 a){a=floor(a);return fract(a.x/2.+a.y*a.y*.75);}
float bayer(vec2 a){return bayer2(a*.125)*.015625+bayer2(a*.25)*.0625+bayer2(a*.5)*.25+bayer2(a);}

void main(){
  vec2 cell=floor(gl_FragCoord.xy/px)*px+px*.5;
  vec2 st=vec2(cell.x/res.x,1.-cell.y/res.y);           // 0..1, y down
  vec2 pp=st*pond;                                       // pond pixels
  float unit=min(pond.x,pond.y);
  vec2 bend=vec2(0.);float glint=0.;
  for(int i=0;i<${MAX_RIPPLES};i++){
    if(i>=ripN)break;
    vec4 r=rip[i];if(r.z<0.)continue;
    float speed=ripKind[i].x*unit,life=ripKind[i].y;
    vec2 d=pp-r.xy;float dist=length(d);
    float front=r.z*speed,lambda=unit*.035;
    float x=(dist-front)/lambda;
    // a short wave packet travelling outward, fading with age and distance
    float env=exp(-x*x*.35)*r.w*(1.-r.z/life)*(1.-r.z/life);
    float wave=sin(x*2.4)*env;
    bend+=d/max(dist,1.)*wave*unit*.012;
    glint+=max(0.,-cos(x*2.4))*env;
  }
  vec2 sp=(pp+bend)/pond;
  vec4 s=texture2D(scene,clamp(sp,vec2(.001),vec2(.999)));
  // water: deeper toward the edges, slow light drifting across, caustics on the floor
  vec2 q=pp/unit*3.;
  float depth=smoothstep(.0,.75,length((st-.5)*vec2(1.2,1.)));
  vec3 water=mix(shallow,deep,depth*.8+noise(q*.35+t*.02)*.2);
  water+=caustic(q)*.08*(1.-depth*.6);
  vec3 col=mix(water,s.rgb,s.a);
  col+=glint*.22;
  if(mode<.5){
    float l=dot(col,vec3(.299,.587,.114));
    l=pow(clamp(l*1.25,0.,1.),.85);
    float th=bayer(gl_FragCoord.xy/px)-.5;
    float k=clamp(l*3.+th,0.,3.);
    vec3 o=k<1.?mix(c0,c1,step(.5,k)):k<2.?mix(c1,c2,step(1.5,k)):mix(c2,c3,step(2.5,k));
    gl_FragColor=vec4(o,1.);
  }else{
    float g=(hash(cell+fract(t))-.5)*.035;
    gl_FragColor=vec4(col+g,1.);
  }
}`;

const hex = (h: string) => { const n = parseInt(h.replace("#", ""), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; };
const KIND: Record<Ripple["kind"], [number, number]> = { tap: [0.42, 2.6], drop: [0.3, 1.6], nibble: [0.22, 1.0], wake: [0.25, 1.0] };

export interface Look { mode: "dither" | "color" | "ink"; palette: [string, string, string, string]; deep: string; shallow: string; tint?: string; pixel: number; bright?: number; floor?: "sand" | "stones" | "pebbles"; caustics?: number; clarity?: number; waves?: number; film?: boolean; absorb?: [number, number, number] }

export function createWater(canvas: HTMLCanvasElement) {
  const gl = canvas.getContext("webgl", { antialias: false, premultipliedAlpha: false, preserveDrawingBuffer: true });
  if (!gl) return null;
  const sh = (type: number, src: string) => { const s = gl.createShader(type)!; gl.shaderSource(s, src); gl.compileShader(s); if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || "shader"); return s; };
  const prog = gl.createProgram()!;
  gl.attachShader(prog, sh(gl.VERTEX_SHADER, VERT)); gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FRAG)); gl.linkProgram(prog); gl.useProgram(prog);
  const buf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, "p"); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  const tex = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  const U = (n: string) => gl.getUniformLocation(prog, n);
  const rip = new Float32Array(MAX_RIPPLES * 4), kinds = new Float32Array(MAX_RIPPLES * 2);

  return {
    render(scene: HTMLCanvasElement, pondW: number, pondH: number, ripples: Ripple[], t: number, look: Look, dpr: number) {
      gl.viewport(0, 0, canvas.width, canvas.height);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, scene);
      const n = Math.min(MAX_RIPPLES, ripples.length);
      for (let i = 0; i < n; i++) {
        const r = ripples[ripples.length - n + i];
        rip.set([r.x, r.y, r.age, r.power], i * 4); kinds.set(KIND[r.kind], i * 2);
      }
      gl.uniform4fv(U("rip"), rip); gl.uniform2fv(U("ripKind"), kinds); gl.uniform1i(U("ripN"), n);
      gl.uniform2f(U("res"), canvas.width, canvas.height); gl.uniform2f(U("pond"), pondW, pondH);
      gl.uniform1f(U("t"), t); gl.uniform1f(U("px"), Math.max(1, look.pixel * dpr)); gl.uniform1f(U("mode"), look.mode === "dither" ? 0 : 1);
      gl.uniform3fv(U("deep"), hex(look.deep)); gl.uniform3fv(U("shallow"), hex(look.shallow));
      look.palette.forEach((c, i) => gl.uniform3fv(U(`c${i}`), hex(c)));
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    },
  };
}

// koipond — koi as real 3D geometry, rendered with three.js.
//
// Each koi body is a tube built around its posed spine: at every point along the body a rounded
// cross-section (wider than tall, like a real koi seen from above), so the surface has true normals.
// It is lit by a low sun and a soft sky with a physically based material: a painted pattern texture
// (unique per fish), a wet clear-coat sheen, metallic scales on gold koi, and a fine scale relief.
// Fins and the tail are thin translucent membranes with rays that bend with the body.
// The scene is drawn from straight above into its own transparent canvas; the water pass then
// refracts it, fades it with depth and uses its silhouette for the shadows on the pond floor.
import * as THREE from "three";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import type { Fish, Pond, V } from "./sim";

const RINGS = 28, SIDES = 14;

function catmull(p: V[], t: number): V {
  const n = p.length - 1, x = t * n, i = Math.min(n - 1, Math.floor(x)), f = x - i;
  const p0 = p[Math.max(0, i - 1)], p1 = p[i], p2 = p[i + 1], p3 = p[Math.min(n, i + 2)];
  const f2 = f * f, f3 = f2 * f;
  const k = (a: number, b: number, c: number, d: number) => 0.5 * (2 * b + (-a + c) * f + (2 * a - 5 * b + 4 * c - d) * f2 + (-a + 3 * b - 3 * c + d) * f3);
  return { x: k(p0.x, p1.x, p2.x, p3.x), y: k(p0.y, p1.y, p2.y, p3.y) };
}

/** Body half-width along its length: blunt rounded head, fullest at the shoulders, long taper to the tail. */
function width(s: number) {
  if (s < 0.24) { const k = s / 0.24; return 0.36 + 0.64 * Math.sqrt(1 - (1 - k) * (1 - k)); }
  const k = (s - 0.24) / 0.76; return 0.1 + 0.9 * Math.pow(Math.cos(k * Math.PI * 0.5), 1.25);
}

// ------------------------------------------------------------------------------- textures (per fish)
function rand(seed: number) { let s = seed >>> 0 || 1; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }

/** The koi's skin unrolled: u along the body (x), around the body (y, back in the middle). */
function skin(f: Fish): THREE.CanvasTexture {
  const W = 512, H = 128, c = document.createElement("canvas"); c.width = W; c.height = H;
  const g = c.getContext("2d")!, r = rand(f.id * 7919 + 13), v = f.variety;
  g.fillStyle = v.base; g.fillRect(0, 0, W, H);
  // markings: clusters of soft-edged blobs, mostly over the back, never on the belly edges
  const blob = (x: number, y: number, rx: number, ry: number, col: string) => {
    g.save(); g.filter = "blur(2px)"; g.fillStyle = col; g.beginPath();
    const n = 9; for (let i = 0; i <= n; i++) { const a = (i / n) * Math.PI * 2, wob = 0.75 + r() * 0.5; const px = x + Math.cos(a) * rx * wob, py = y + Math.sin(a) * ry * wob; i ? g.lineTo(px, py) : g.moveTo(px, py); }
    g.closePath(); g.fill(); g.restore();
  };
  if (v.name === "minnow") { const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t; }
  if (v.name === "tancho") blob(W * 0.07, H * 0.5, W * 0.05, H * 0.22, "#e2380f");
  let cover = 0;
  while (cover < v.spotCover) {
    const x = W * (0.04 + r() * 0.82), y = H * (0.5 + (r() - 0.5) * 0.45), rx = W * (0.05 + r() * 0.09), ry = H * (0.16 + r() * 0.2), col = v.spots[Math.floor(r() * v.spots.length)];
    blob(x, y, rx, ry, col); blob(x + (r() - 0.5) * rx, y + (r() - 0.5) * ry, rx * 0.6, ry * 0.7, col);
    cover += (rx / W) * (ry / H) * 4;
  }
  // a darker line down the back and paler flanks, as real koi have
  const back = g.createLinearGradient(0, 0, 0, H);
  back.addColorStop(0, "rgba(255,255,255,0.18)"); back.addColorStop(0.5, "rgba(0,0,0,0.08)"); back.addColorStop(1, "rgba(255,255,255,0.18)");
  g.fillStyle = back; g.fillRect(0, 0, W, H);
  // eyes on the sides of the head
  g.fillStyle = "#0a090c";
  for (const y of [H * 0.2, H * 0.8]) { g.beginPath(); g.ellipse(W * 0.05, y, 4, 5, 0, 0, Math.PI * 2); g.fill(); }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
  return t;
}

let scaleTex: THREE.CanvasTexture | null = null;
/** A shared relief of small overlapping scales, used as a bump map. */
function scales(): THREE.CanvasTexture {
  if (scaleTex) return scaleTex;
  const W = 512, H = 128, c = document.createElement("canvas"); c.width = W; c.height = H;
  const g = c.getContext("2d")!; g.fillStyle = "#808080"; g.fillRect(0, 0, W, H);
  const sx = 11, sy = 9;
  for (let row = 0; row < H / sy + 1; row++) for (let col = 0; col < W / sx + 1; col++) {
    const x = col * sx + (row % 2) * sx * 0.5, y = row * sy;
    const grd = g.createRadialGradient(x - 2, y, 0, x, y, sx * 0.8);
    grd.addColorStop(0, "#b0b0b0"); grd.addColorStop(0.8, "#808080"); grd.addColorStop(1, "#505050");
    g.fillStyle = grd; g.beginPath(); g.arc(x, y, sx * 0.75, -Math.PI / 2, Math.PI / 2); g.fill();
  }
  scaleTex = new THREE.CanvasTexture(c); scaleTex.wrapS = scaleTex.wrapT = THREE.RepeatWrapping;
  return scaleTex;
}

let finTex: THREE.CanvasTexture | null = null;
/** Fin membrane: rays fanning out, thin and bright, darker at the frayed edge. */
function fins(): THREE.CanvasTexture {
  if (finTex) return finTex;
  const W = 256, H = 256, c = document.createElement("canvas"); c.width = W; c.height = H;
  const g = c.getContext("2d")!;
  const grd = g.createLinearGradient(0, 0, W, 0);
  grd.addColorStop(0, "rgba(255,255,255,0.75)"); grd.addColorStop(0.75, "rgba(255,255,255,0.45)"); grd.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grd; g.fillRect(0, 0, W, H);
  g.strokeStyle = "rgba(255,255,255,0.55)"; g.lineWidth = 1.2;
  for (let i = 0; i <= 26; i++) { const y = (i / 26) * H; g.beginPath(); g.moveTo(0, y); g.lineTo(W * 0.98, y + (i - 13) * 1.5); g.stroke(); }
  finTex = new THREE.CanvasTexture(c); finTex.colorSpace = THREE.SRGBColorSpace;
  return finTex;
}

// ------------------------------------------------------------------------------- the renderer
type Koi = { body: THREE.Mesh; fins: THREE.Mesh[]; tail: THREE.Mesh; mat: THREE.MeshPhysicalMaterial; finMat: THREE.MeshBasicMaterial };

function strip(n: number) {
  // a grid of (n+1) x 2 vertices with triangles, used for fins and the tail
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(new Float32Array((n + 1) * 2 * 3), 3));
  const uv = new Float32Array((n + 1) * 2 * 2);
  for (let i = 0; i <= n; i++) { uv.set([0, i / n, 1, i / n], i * 4); }
  geo.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
  const idx: number[] = [];
  for (let i = 0; i < n; i++) { const a = i * 2; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
  geo.setIndex(idx);
  return geo;
}

export function createFish3D(renderer: THREE.WebGLRenderer) {
  // draws into its own render target on the shared renderer; the stage samples it directly
  const target = new THREE.WebGLRenderTarget(1, 1, { samples: 4, depthBuffer: true });
    const scene = new THREE.Scene();
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.18;
  const sun = new THREE.DirectionalLight(0xfff4e0, 1.7); sun.position.set(-0.45, -0.6, 1); scene.add(sun);
  scene.add(new THREE.HemisphereLight(0xf2efe4, 0x8a8a70, 1.25));
  const cam = new THREE.OrthographicCamera(0, 1, 0, 1, -500, 500);
  cam.position.set(0, 0, 100); cam.up.set(0, 1, 0); cam.lookAt(0, 0, 0);
  const kois = new Map<number, Koi>();

  const build = (f: Fish): Koi => {
    const geo = new THREE.BufferGeometry();
    const nv = (RINGS + 1) * (SIDES + 1);
    geo.setAttribute("position", new THREE.BufferAttribute(new Float32Array(nv * 3), 3));
    const uv = new Float32Array(nv * 2);
    for (let i = 0; i <= RINGS; i++) for (let j = 0; j <= SIDES; j++) uv.set([i / RINGS, j / SIDES], (i * (SIDES + 1) + j) * 2);
    geo.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
    const idx: number[] = [];
    for (let i = 0; i < RINGS; i++) for (let j = 0; j < SIDES; j++) { const a = i * (SIDES + 1) + j, b = a + SIDES + 1; idx.push(a, b, a + 1, b, b + 1, a + 1); }
    geo.setIndex(idx);
    const gold = f.variety.name === "ogon" || f.variety.name === "yamabuki";
    const mat = new THREE.MeshPhysicalMaterial({
      map: skin(f), bumpMap: scales(), bumpScale: 0.35, roughness: gold ? 0.4 : 0.55, metalness: gold ? 0.3 : 0.0,
      clearcoat: 0.3, clearcoatRoughness: 0.4, side: THREE.DoubleSide,
    });
    const body = new THREE.Mesh(geo, mat); scene.add(body);
    const finMat = new THREE.MeshBasicMaterial({ map: fins(), color: new THREE.Color(f.variety.fin).lerp(new THREE.Color("#f3eee4"), 0.25), transparent: true, opacity: 0.68, side: THREE.DoubleSide, depthWrite: false, premultipliedAlpha: true });
    const fms: THREE.Mesh[] = [];
    for (let k = 0; k < 4; k++) { const m = new THREE.Mesh(strip(8), finMat); scene.add(m); fms.push(m); }
    const dorsal = new THREE.Mesh(strip(10), finMat); scene.add(dorsal); fms.push(dorsal);
    const tailGeo = strip(14), tuv = tailGeo.getAttribute("uv") as THREE.BufferAttribute;
    for (let q = 0; q <= 14; q++) { tuv.setXY(q * 2, q / 14, 0); tuv.setXY(q * 2 + 1, q / 14, 1); } // rays run along the tail
    const tail = new THREE.Mesh(tailGeo, finMat); scene.add(tail);
    return { body, fins: fms, tail, mat, finMat };
  };

  const water = new THREE.Color("#3b5e58");
  return {
    texture: target.texture,
    render(pond: Pond, w: number, h: number) {
      if (target.width !== w || target.height !== h) target.setSize(w, h);
      cam.left = 0; cam.right = pond.w; cam.top = 0; cam.bottom = pond.h; cam.updateProjectionMatrix();
      const alive = new Set<number>();
      for (const f of pond.fish) {
        alive.add(f.id);
        const k = kois.get(f.id) ?? (kois.set(f.id, build(f)), kois.get(f.id)!);
        const pose = pond.pose(f), pts: V[] = [], tg: V[] = [];
        for (let i = 0; i <= RINGS; i++) pts.push(catmull(pose, i / RINGS));
        for (let i = 0; i <= RINGS; i++) { const a = pts[Math.max(0, i - 1)], b = pts[Math.min(RINGS, i + 1)], l = Math.hypot(a.x - b.x, a.y - b.y) || 1; tg.push({ x: (a.x - b.x) / l, y: (a.y - b.y) / l }); }
        const z0 = -f.depth * f.girth * 3; // deeper fish sit lower
        // body: rounded cross-sections, a little flatter on the back than a circle
        const pos = k.body.geometry.getAttribute("position") as THREE.BufferAttribute;
        for (let i = 0; i <= RINGS; i++) {
          const s = i / RINGS, wd = f.girth * width(s), ht = wd * 0.78, nx = -tg[i].y, ny = tg[i].x;
          for (let j = 0; j <= SIDES; j++) {
            const th = (j / SIDES) * Math.PI, cx = Math.cos(th), cz = Math.sin(th);
            // nose: pull the first ring in so the snout is rounded, not cut off
            const nose = i === 0 ? 0.0 : 1;
            pos.setXYZ(i * (SIDES + 1) + j, pts[i].x + nx * cx * wd * nose + tg[i].x * (i === 0 ? f.girth * 0.25 : 0), pts[i].y + ny * cx * wd * nose + tg[i].y * (i === 0 ? f.girth * 0.25 : 0), z0 + cz * ht);
          }
        }
        pos.needsUpdate = true; k.body.geometry.computeVertexNormals();
        k.mat.color.copy(new THREE.Color(1, 1, 1).lerp(water, f.depth * 0.18));
        k.finMat.opacity = 0.68 - f.depth * 0.15;
        // pectoral and pelvic fins: membranes swept back from the body, paddling gently
        const paddle = 0.85 + 0.2 * Math.sin(f.finPhase * 2.2);
        let fi = 0;
        for (const [s0, size, sweep] of [[0.25, 1.9, 0.75], [0.6, 0.95, 0.6]] as const) {
          const i = Math.round(s0 * RINGS), base = pts[i], t = tg[i];
          for (const side of [1, -1]) {
            const nx = -t.y * side, ny = t.x * side, reach = f.girth * size * paddle * (1 - Math.max(0, side * f.turn) * 0.3);
            const geo = k.fins[fi++].geometry, p = geo.getAttribute("position") as THREE.BufferAttribute;
            for (let q = 0; q <= 8; q++) {
              const u = q / 8, root = { x: base.x + nx * f.girth * width(s0) * 0.8 + t.x * f.girth * (0.5 - u), y: base.y + ny * f.girth * width(s0) * 0.8 + t.y * f.girth * (0.5 - u) };
              const ang = sweep * (0.4 + u), dx = nx * Math.cos(ang) - t.x * Math.sin(ang), dy = ny * Math.cos(ang) - t.y * Math.sin(ang), len = reach * Math.sin(Math.PI * (0.15 + u * 0.85)) ** 0.7;
              p.setXYZ(q * 2, root.x, root.y, z0 + f.girth * 0.1); p.setXYZ(q * 2 + 1, root.x + dx * len, root.y + dy * len, z0 - f.girth * 0.05);
            }
